/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231005-4","meetingId":"r05-c-settlement","date":"2023年10月5日","dateIso":"2023-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を155件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"おはようあります。本日もどうぞよろしくお願いします。２７３ページ、病児保育、２６５ページ、子どもの未来応援事業についてお伺いいたします。そこでお伺いいたします。どうしても仕事に行かなければならない状況に陥った保護者が、安心して働けるように、病児保育の対象年齢を小学校１年生から３年生くらいまでに拡充していただきたいと要望いたしますが、区としては、どのようにお考えでしょうか。","respondent":"立木保育課長","answer":"そうした中で、まずは１歳児のご利用者数のところをしっかりカバーできるような施設の充実を図った上で、年齢の拡大については、そういったところで検討をさせていただきたいというふうに考えているところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"今ない東側のエリアに病児保育施設をつくっていただくということを進めてくださっているということと、あと、年齢についても検討していただけるということですけれども、例えばですが、今現在、稼働している病児保育についても、空きが出ているときには、小学生でも利用できるように柔軟に対応していただけるように、区として働きかけていただくことはできますでしょうか。区としての見解をお聞かせください。","respondent":"立木保育課長","answer":"年齢拡大の部分に関しましては、確かに空いている状況も日によってはありますので、施設のハード・ソフトの面で対応が可能かどうかというところもありますが、そうしたところを、実施者と、今後協議は進めていきたいというふうに考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ今後、病児保育の対象年齢や施設を拡充していただきたいと思うのですけれども、施設の場所や人材の確保など様々な課題もあると思います。広く事業者を募集するとともに、空き家を利用してリノベーションするなど、働きながら子育てをする保護者のセーフティネットとしての病児保育は、ぜひ拡充していただきたいと改めて要望いたします。続きまして、子どもの未来応援事業についてお伺いいたします。","respondent":"飛田子育て応援課長","answer":"３点ほど質問がありました。寄附額が増えた要因については、なかなか分析は難しいところですが、こちらの事業は、令和元年度から始めて昨年度で４回目となりました。ふるさと納税の周知や定着が考えられるのかと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問・要望","question":"食品以外のトイレットペーパーやスポンジ、洗剤などの日用品の同封を今後も継続していただきたいとの要望をいただいておりますので、区が行っている食品配送におかれましても、食品とともに日用品同封の継続を検討していただきたいと思いますが、区としての見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"中には、食品のほかに化粧水なども入っていて、大変ご好評をいただいているところですが、あくまでガバメントクラウドファンディング、こちらの寄附のところでは、子どもたちの食の支援へのご協力をお願いしますとうたっておりますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"専門校などで半年以上学ぶ機会に必要な生活費として、毎月１０万円を来年度から恒久的に給付していくようです。できることならば、この施策がスタートする前にも、始まりますよとのお知らせと、また、始まった後にも改めてご紹介するというように、繰り返し周知していただくことも大切なのかと思いますけれども、区としてのご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"いずれにしましても、各家庭の自立を目指して支援に結びつけられるよう、これからも取り組んでまいりたいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"子どもを育てるひとり親の自立支援として、この情報がなるべく多くの方に伝わって活用されることを望んでおります。これからもガバメントクラウドファンディングにより、多くの寄附が集まり、しあわせ食卓事業がより一層充実していくことを期待しております。どうぞよろしくお願いいたします。以上、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、障害者支援費から２点お伺いいたします。２３３ページの地域生活支援事業、２３４ページの日常生活用具給付事業について、それぞれお伺いしてまいります。現場や視覚障害者福祉協会の団体からは、通勤に介助の支援が使えればというお声があり、強いニーズの高まりを感じつつありますが、まず、本区での視覚障害者の同行支援についての現状の課題、認識をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"シルバーセンターマッサージでは、報酬を受けとられることによって経済的な支援とみなされ、国では同行援護の対象とはなりませんでした。非常に私たちも悩みまして、今、研究を進めているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"繰り返しになりますが、現場からの声、また、視覚障害者福祉協会の団体からの要望も受け、本年も継続して公明党の会派要望として上げさせていただいている内容でもあります。他自治体の動向を見てもニーズが高まりつつあるものと思われ、現場からの切なる願いでもあります。この重度障害者等就労支援特別事業について、改めて本区でのお考えをお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"障害者団体からのご要望をいただいておりまして、こちらの重度障害者就労支援特別事業の導入により、課題解決の可能性もありますので、今後、他区の状況も確認しつつ、視覚障害者団体のお声も伺いながら検討を進めていきたいと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"前向きなご答弁、誠にありがとうあります。続いて、日常生活用具給付事業について質問いたします。品川区で、視覚障害者への日常生活の援助として支給することができる携帯用会話補助装置、活字文書読み上げ装置について、どういったものなのか、また、ここ数年の、支給実績や活用された現場の声などがもし分かれば教えていただければと思います。","respondent":"松山障害者支援課長","answer":"視覚障害者の方にご利用いただいているのですが、この機器が、幅、高さ、奥行きが１０cm程度の立方体のものでして、少し持ち運びに不便だというお声をいただいておりまして、こちらのほうの実績はございません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"先日、日本点字図書館に個人的に行ってまいりました。アプリはカタログ等で視覚・聴覚等障害者の日常生活に資することが確認できるアプリであれば、有料、無料を問わず対象としています。どうか時代に即して、日常生活用具にｉＰａｄやｉＰｈｏｎｅ等の端末を、音声読み上げソフト、メールソフト以外の視覚障害者向けソフトを追加することを要望しますが、区のお考えをお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"他の状況も確認しますので、毎年行っております日常生活用具検討会で、視覚障害者団体、また、ほかの団体のお声を聞きながら、今後、具体的に検討を進めていきたいと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"中野区では、既に里親認定証として関係性が証明できるものを作成して活用しているようなのですが、品川区では、里親証明書などの作成は考えているのでしょうか、区のお考えをお聞かせください。ぜひ失語症で困っている方々のために、失語症者向けの意思疎通支援者の派遣事業も、東京都の制度を利用しながら進めていただきたいと思うのですが、いかがでしょうか。それぞれお考えをお聞かせください。","respondent":"飛田子育て応援課長、川原高齢者地域支援課長、長谷川児童相談所開設準備課長、松山障害者支援課長","answer":"こちらは東京都の私学財団での授業料の負担軽減の世帯年収の目安が９１０万円未満の世帯となっておりますので。今後につきましては、高齢者クラブそのものも老人福祉法に定められている高齢者福祉を増進するための事業を行うものですので、行政としても。ただし、区が認定証をつくったとしても、銀行がどのように扱うのかはこちらのほうで制御が利かない部分にもなりますので。それで支援者を確保するということが大事だと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１つ目の奨学金貸付事業についてですが、入学準備金の貸付利用者は少ないということが分かりました。制度が必要な人にしっかりと情報が周知できるよう、引き続き取り組んでいただきたいと思います。２つ目に、高齢者クラブ支援事業についてですが、高齢者クラブの現状、そして課題が分かりました。現在、外国籍の里子も増えてきているとの話も伺っております。こちらは重ねての要望とします。","respondent":"飛田子育て応援課長、川原高齢者地域支援課長、長谷川児童相談所開設準備課長","answer":"在学応援資金ということで、在学が条件になっているのですが、途中で高校を辞めてしまったりとか、そういうこともありましたので、その方は。いただいたご意見につきましては、今後、連合会の会長である副会長の皆様と協議を重ねながら工夫をして ＰＲの強化を図ってまいりたいと思います。区としましても、導入予定のフォスタリング機関と密に連携をし、里親のリクルートを進めるとともに。","voiceIndex":33,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"高齢者クラブ支援事業については、またご検討いただけるということで、前向きな答弁だと確認いたしました。そして、児童相談所開設準備事業については、これからの開設ということもありますが、開設の準備の段階で運用に向けて検討を様々と進めていただければと思いますので、引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"私立保育園経費なのですけれども、私、今年２月の一般質問と、３月の予算特別委員会で、保育所への、定員割れ私立保育施設への加算制度について伺いました。２歳児が満杯になったのは９月でした。保育支援課長は代わっていますけれども、ほとんどの区でも行っている定員割れ私立保育施設への加算を行うことが経営努力を阻害する要因になるというのは、なぜそうなるのか伺いたいと思います。","respondent":"石井保育支援課長","answer":"一義的に補填をすることが、そういった努力しようとしている事業者の工夫の妨げになるのではないか、そう考えているところです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"もうける、もうけないの話ではないのですから。それを品川区は、今、２倍以上の数を私立に、多くは株式会社ですけれども、担ってもらっているわけではないですか。もう少し伺いたいのですけれども、経営努力と言いましたけれども、その経営努力とは、子どもの数に応じて保育園の数を減らしなさいよと、人件費を削減しなさいよと、そういうことを差して言っているのでしょうか。もう一度伺いたいと思います。","respondent":"石井保育支援課長","answer":"先ほども申しましたが、園児数が減ったことによって保育園を減らす、これは経営努力ということではなく、様々な園児獲得のための努力、空きスペースや空き定員を活用した新たな事業、そういったことが経営努力につながると考えています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"そこで、保育士がスキルを積み上げて、子どもの育ち、保護者の支援を行うスキルを身につけていくわけではないですか。２３区調査で分かりました。伺いますけれども、安定した保育の実施、これまで品川区の保育を担ってきた地域の保育園の存続、ひいては品川区の子どもたちが生き生き伸び伸びと育つ環境をつくるために、定員定額制を品川区でも検討すべきではないのでしょうか。改めて伺います。","respondent":"石井保育支援課長","answer":"処遇改善臨時特例事業について、一時的なものではなく恒久的にというふうなお話がありましたけれども、既に国において処遇改善等加算IIIということで公定価格の中に組み込まれており、認証保育所運営費の中でもその分が工面されているところですので。","voiceIndex":43,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"毎年、私たち共産党をはじめ、議会は様々な団体から要望を伺うわけです。でも、それでもなお実態は厳しいということをぜひ直視していただいて、他区を参考にして、実態に即した支援をお願いしたいと改めて要望します。少し細かい話でまず伺うのですけれども、例えば、タクシー料金が２,１００円でした。こういう場合に、おつりは出るのでしょうか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"福祉タクシー券の利用の仕方についてのご質問です。先ほど委員がおっしゃった計算ですと、おつりとしては出ません。ただし、その場合、現金をお支払いいただくという方法はあります。","voiceIndex":45,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、私は、１００円券、内訳が一月にすると５枚なのですけれども、すぐにでもこれを増やすべきだと思うのです。少なくとも１０枚に増やすべきだと思います。当事者団体からも毎年要望が上がっていて、これまでも共産党を含め、一般質問でもありましたし、何度も質疑もされたと思うのですけれども、なぜ増やしていただけないのでしょうか。なぜやらないのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"福祉ＤｉＤｉタクシー券利用券の１００円券の交付枚数を増やしてほしいというご要望をいただく一方で、１００円券を増やすと非常に扱いにくいというご要望もいただいておりまして、利用者の声としては様々な声があるため、今の状態で調整させていただいているです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは、もっとよく声を聞いていただきたいと、ぜひ改善していただきたいというふうに思います。タクシー料金も、昨年１１月に１５年ぶりに初乗り料金、メーター加算料金とも上がったということです。やはり視覚障害者の外出を保障するために、補正にとどまらず、金額そのものを上げるべきだと思いますけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"福祉タクシー券のご要望です。対象者の方として、下肢体幹や視覚障害、内部障害、愛の手帳をお持ちの方がいらっしゃいます。今後も利用者の状況、今後の物価の推移を見ながら、さらなる検討をしてまいります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。今まで地域包括ケアシステムというものがありまして、私としては、一見同じようなものなのかなと思ってしまうのですけれども、今までの地域包括ケアシステムとの違い、重層的支援体制整備がなされたら、今までとどう変わっていくのか、どうよくなっていくのか、その点をお伺いいたします。","respondent":"東野福祉計画課長","answer":"今まで、そういった意味では、以前から地域包括ケアシステムに区のほうでも取り組んでまいりましたが、今言った相談支援、参加支援、地域づくりに向けた支援に向けまして、新たな体制を区としてつくっていくということで、現在、取り組んでいるものです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"今現在、第８期品川区介護保険制度推進委員会等でこのことについてご検討されていると思うのですけれども、今までの委員会などで出た議論の中で、今後、品川区が重層的支援体制をやっていく中で、課題があるのでしょうか。この委員会でも、支え愛・ほっとステーションのことが取り上げられているかと思うのですけれども、今後の支え愛・ほっとステーションの役割をお聞かせください。","respondent":"東野福祉計画課長","answer":"そういったところとの結びつきをいかにして進めるかというところで、今、検討を進めているものでございまして、区として、どう取り組んでいくか、区民への浸透がこれからの課題となってくるかと考えています。","voiceIndex":54,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"よく分かりました。支え愛・ほっとステーションが核ということなのですけれども、この支え愛・ほっとステーションは、１０年ほど前、モデル事業としてスタートしたと認識しておりますけれども、この「支え愛・ほっとステーション」という事業名の由来、また、ほかの区では同様の事業はあるのでしょうか。お聞かせください。","respondent":"東野福祉計画課長","answer":"支え愛・ほっとステーションにつきましては、これまでも社会福祉協議会に区が委託をして進めてきたという経緯がございまして、福祉的なところを補っていただいているというような位置づけとなっています。","voiceIndex":58,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"なぜこのような質問をさせていただいたかといいますと、この周知について、ホームページや広報紙等々で周知されているということなのですけれども、今、マンション内とかでも掲示されていることかと思います。その点、どうお考えなのでしょうか。","respondent":"東野福祉計画課長","answer":"今後もこういったパンフレットの配布、周知、それから、今、ＳＮＳなどでも取り上げて、周知を図っていきたいというふうに考えているところです。","voiceIndex":60,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。引き続き積極的な周知をお願いしたいと思います。対象が一人暮らしの方のように、何かそればかり、一人暮らしの方しか対象ではないような書きぶりも、そういうふうに見えてしまうので、ご説明の仕方の今後の在り方もぜひ検討していただきたいと考えております。確かに似たような事業はなるべくまとめて整理されるべきかなと考えておりますけれども、その点、いかがお考えなのでしょうか。","respondent":"東野福祉計画課長","answer":"そういった事業との重なりが出てきているということは現実にあろうかと思いますので、その点につきましては、支え愛活動の部分を今後どうしていくかということで、所管のほうで検討に入っているというふうに伺っております。","voiceIndex":62,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、開催場所も４か所でありまして、また、ｉＰｈｏｎｅとＡｎｄｒｏｉｄで分けているということで、そうすると、結局、ｉＰｈｏｎｅ２か所、Ａｎｄｒｏｉｄ２か所というような、どんどん細分化されて、教室を受ける機会が減っていってしまうと思うのですけれども、開催場所も４か所からもっともっと増やすべきでありますし、ｉＰｈｏｎｅ、Ａｎｄｒｏｉｄの分け方も。","respondent":"川原高齢者地域支援課長","answer":"１点目、デジタルデバイドの対策として、知らない方もまだいるのではないか、その方への周知はどうするかですが、今、スマホ教室は２種類あるのですけれども、１か所がシニアがシニアを教えるというシニアのためのスマホ教室。","voiceIndex":64,"id":"exchange-025"},{"speaker":"筒井委員","kind":"意見","question":"今後はどんどん高齢者の方もスマホをぜひ使いこなしていってほしいですし、世の中のＤＸ化で取り残されてしまう、ひいては、社会全体の活性化の遅れということになってもきますので、この高齢者向けパソコン・スマホ教室の拡充をぜひよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"２７１ページの就学前教育推進費から質問いたします。のびしなプロフェッショナルスクールについて、保育者に向けた研修を開催していると思いますが、この研修の内容は、「のびのび育つしながわっこ」という保育・教育のガイドラインに沿って行われているのでしょうか。ガイドラインの改定が平成３０年度に行われたという記載を確認しています。次の改定時期はいつでしょうか。","respondent":"立木保育課長","answer":"今後の子ども・子育ての部分に関しまして、しっかり見極めた上で、区の保育指針に関する部分も、それを盛り込んだ形で検討してまいりたいと考えていますので、こども大綱ですとか、そういったものを見極めた以後に、というふうに今は考えているところです。","voiceIndex":68,"id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"ご説明いただきまして、ありがとうあります。質問するのですけれども、今、学校でも性教育を早期から導入するべきという意見でしたり、幼児期からの性教育についての書籍も多く出版されている現状があります。子どもに対する犯罪防止には、対策や知識をアップデートをしていくことが求められていると考えます。後ほど、私立園での状況もお聞きしますが、まず区立園のことでお願いします。","respondent":"立木保育課長","answer":"特に明確な形で、例えば、クラスの中でそういう時間を設けているかというと、そういうことではないのですけれども、日々の保育の中で、例えばトイレに行っているときとか、あと、着替えの場面ですとか、そういった保育の中での場面を捉えまして、保育者から子どもたちに。","voiceIndex":70,"id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"とてもいい取組だと思います。保護者会等で保護者への情報共有をして知識のアップデートを進めるべきだと思いますが、いかがでしょうか。それも１つの職場環境で、退職者だったり、保育士の人手不足の原因にもなりかねないとも思います。お互いに自分を守るための保育・教育をお願いしたいと思いますが、こちらは区の見解を伺います。","respondent":"立木保育課長","answer":"職員に関しましては、これは、のびしなプロフェッショナルスクールの中でも、何かそういういいものがあれば、取り入れていきたいというふうに考えております。","voiceIndex":72,"id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"ぜひ多くの園で実施して、保護者への説明等も実施していただけると幸いです。私立保育園で伺います。このような取組を私立保育園でもするべきだと思いますが、園児へのプライベートゾーンのお話や、保護者会での幼児からの性教育情報の共有については、いかがでしょうか。","respondent":"石井保育支援課長","answer":"そこでは、水着で隠れるところはプライベートゾーン、大事なところだよということで園児に教えるということですとか、あと、保護者への子どもの性被害に関する知識の周知、こういったことの依頼がありますので、区としましても。","voiceIndex":74,"id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちらは、学校では既に周知がされていると会議録でも確認しておりまして、その幼児向け教材とともに、文部科学省と内閣府が連携して作成された、園で子どもたちに伝えるための指導の手引きが公開されていますので、のびしなプロフェッショナルスクール、保育士研修などでもぜひ取り入れていただきたいと思います。こちらについて、ご意見をお聞かせいただきたいです。","respondent":"立木保育課長","answer":"こちらは区立保育園においてもしっかり取り入れて考えていきたいというふうに考えておりますが、のびしなプロフェッショナルスクール等の場を使いまして、そういったものに適用できるような形で何かしら考えていきたいと思います。","voiceIndex":76,"id":"exchange-031"},{"speaker":"せらく委員","kind":"意見","question":"子どもの大事な命を守るためにも、保育環境を引き続きよくしていただきますよう、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私からは、２５７ページ、青少年育成事業、児童相談所移管推進事業、２５９ページ、児童相談事業、ヤングケアラー支援事業についてお伺いいたします。私は、今年８月、警視庁大森少年センターの取組について、黛前所長からお話を伺いました。区として現在の課題をどのように捉えていますでしょうか。そして、今後の少年センターや警察などとの連携の在り方について、区のお考えをお聞かせください。","respondent":"染谷子ども家庭支援センター長","answer":"保護者からの相談につきましては、より専門性の高い、先ほど委員からお話がありました大森少年センターをご紹介するとか、つなぐといった形で対応していますし、また、非行相談に限らず、虐待も含めまして、日頃、各警察署の生活安全課少年係と連携。","voiceIndex":80,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"大人のチンパンジー同士の場合、群れと群れのチンパンジーを交換したりするケースも同じように、やはり１対１で、人間でいうと差し飲みというのでしょうか、１対１という形でお見合いをしていって、扉のところにひまわりの種みたいなものを置いて、少しお茶でも、クッキーでもつまみながらみたいな形で、１体ずつを仲よくしていって、それが全て終わったら群れに戻すというような形をやっているそうです。","respondent":"染谷子ども家庭支援センター長、藤村子ども育成課長","answer":"誰かに聞いてほしい、解決を求めているわけではないという部分につきましても、より気軽に相談いただけるようなＳＮＳの相談窓口を開設しておりますので、そういったところでも継続的にメッセージのやり取りをさせていただきながら。子どもの目線や声を区政に生かすために、区民アンケートを実施しているということは委員もおっしゃっていたとおりですが、児童センターの在り方検討等を踏まえて、中でも意見を取り入れておりますので。","voiceIndex":82,"id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、２３１ページ、手話理解促進、２５７ページ、すまいるスクール運営費からトイレについて、４８２ページ、介護認定審査会費についてお伺いしてまいります。２年が過ぎました。この２年間の品川区の取組をお聞かせいただきたいと思います。そして、今後の取組についてもお伺いいたします。","respondent":"松山障害者支援課長","answer":"現在も活用させていただいているところです。次に、手話講座を拡大してきたことです。令和３年の条例制定以降、区職員向けの手話講座を実施いたしました。","voiceIndex":86,"id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、周知に取り組んでいただきたいと思います。障害のある方、ない方、ともに理解し合える品川区のために、しっかりとお願いしたいと思います。２０２５年の１１月１５日から２６日まで、デフリンピックが開催されます。当然ながら、この事業、アイルしながわで行われます内容に関しては、障害者団体の方との連携はとられているのでしょうか、お伺いいたします。","respondent":"松山障害者支援課長","answer":"委員にご紹介いただいた１０月１４日の「デフスポーツ＆アートフェア」についてです。私どももブースを１つ設けまして、当事者の団体と調整しながら、今、こちらのブース開催に向けて取り組んでいるところです。","voiceIndex":88,"id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"委員長に了解を得ましたので、提示します。ぜひこれに関しては、デフリンピックの意識啓発を進めていく中で、ぜひ団体の方のご要望を伺っていただきながら、ご検討を進めていただきたいと要望をしますので、どうぞよろしくお願いいたします。その後、全てのすまいるスクールのトイレはどうなのかという調査をしていただきまして、現状どうなっているのかということを確認させていただきたいと思います。","respondent":"藤村子ども育成課長","answer":"その後の改修とか改築などによりまして、現在、その１１か所のうちの８か所は、トイレの数が増えたり、洋式化が進んでいるというような状況で改善しているという状況です。","voiceIndex":90,"id":"exchange-037"},{"speaker":"新妻委員","kind":"意見","question":"そうしますと、残り３か所、この３か所につきまして、どういう対応がとられているのか、今後の予定も含めてお知らせください。","respondent":"藤村子ども育成課長","answer":"今後の対応といたしましては、まだ具体的にというところは整っていないのですけれども、教育委員会と協議しまして、例えば、和式を洋式に変えるという検討ができないかですとか、すまいるスクールの階と違うところにトイレがあるようなところについては。","voiceIndex":92,"id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"残り３か所、やはりここがどうしても課題なのかなと思います。構造上なかなか難しいこともあろうかと思うのですけれども、区議会公明党は、学校の中での洋式トイレの推進もしていますが、これまでも何回か要望しています。この３か所について、具体的に、ぜひ洋式化を早急に進めていただきたいと思います。改めて要望しますが、見解を伺います。","respondent":"藤村子ども育成課長","answer":"委員の要望を踏まえまして、教育委員会と協議を進めていきたいと思います。","voiceIndex":94,"id":"exchange-039"},{"speaker":"新妻委員","kind":"質問","question":"ぜひよろしくお願いいたします。すみません、最後の質問は時間がなくなりましたので、以上で終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-040"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２３７ページ、障害児者福祉施設運営費、２４５ページ、福祉人材確保・定着事業についてお伺いします。北品川つばさの家の修繕工事費等に２,９００万円がついていますが、こちらは何の修繕に使われたのでしょうか。内容をお知らせください。","respondent":"松山障害者支援課長","answer":"北品川つばさの家の修繕工事費約２,９００万円余の内訳についてです。空調改修工事およびポンプ更新工事等で１,１６６万円余、脱衣室内装改修工事およびドアチェーン取付工事等で７８万円余、加えて、電気設備更新に伴う改修工事で１,６５８万円余です。","voiceIndex":99,"id":"exchange-041"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。今年の８月に、我が会派で、北品川つばさの家へ視察に伺いました。築年数の古い建物ですので、バリアフリー化がされておらず、日常生活の中でも支障を来すつくりの部分も多く、洗濯物を野外のベランダに干す際にも、１段、２段と段差を上って出入りすることになり、手すりもなく、障害者の方、そして高齢者にも、足元を含めとても危険だと感じました。","respondent":"松山障害者支援課長","answer":"委員ご指摘の手すり等につきましては、利用者が安心して過ごせるよう、現在、指定管理者と協議、調整しています。","voiceIndex":101,"id":"exchange-042"},{"speaker":"えのした委員","kind":"質問・要望","question":"西大井つばさの家にも改修費が７００万円とありますが、令和５年６月１２日、厚生委員会のご答弁では、知的障害者グループホームの改修工事が終わり、令和５年５月からは、対象者が７名から２名増えて９名として事業を実施しているとのこと、こちらはバリアフリー化なども整備されているのでしょうか。内容をお知らせください。","respondent":"松山障害者支援課長","answer":"西大井つばさの家のバリアフリーに関してのご質問です。可能な限り、手すり等はつけられるところにはつけたのですが、構造上、なかなか全て段差が解消できず、あとは、職員が手を添える、必要なところには手すりをつける等、配慮して対応してまいります。","voiceIndex":103,"id":"exchange-043"},{"speaker":"えのした委員","kind":"質問","question":"引き続き、ご対応をお願いいたします。以前、会派としても質問している小山七丁目障害者グループホーム整備について、進捗状況をお知らせください。","respondent":"川崎障害者施策推進課長","answer":"今年度は、事業者公募を経て運営事業者が決まり、既に事業者も町会長へご挨拶をさせていただきました。今後は、運営事業者による住民説明会を開催予定で、令和７年度中に開設を予定しております。","voiceIndex":105,"id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"本当に丁寧な対応をしていただき、感謝申し上げます。続けて、福祉人材確保定着事業についてお伺いします。事業概要には、品川介護福祉専門学校の入学生の増加を図るため、生徒募集活動を支援する取組として、増加を目指し、広報、生徒募集活動等に専任職員１名を配置する人件費を助成したとありますが、学校の入学者数の推移と、また、具体的にどのような成果があったのかお知らせください。","respondent":"菅野高齢者福祉課長","answer":"区および区内社会福祉法人等のバックアップにより、入学から卒業後のキャリアアップまで長きにわたりサポートしておりますが、やはりここ数年、入学者の減少が課題となっており、学校のＰＲの強化等のために、専任の営業職配置を支援しているところです。","voiceIndex":107,"id":"exchange-045"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。私も主要施策の成果報告書を確認しましたが、高校の訪問数２５６件、これは２５６校ということなのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"結果、入学者の増につながったというところで、高校を訪問したときに、この学校に対する認知度を高校で聞いてみたところ、やはり全体の７割程度が、この学校のことを知らなかったというふうに答えておりまして、２割程度の学校が、本校のことを知っていたけれども。","voiceIndex":109,"id":"exchange-046"},{"speaker":"えのした委員","kind":"質問","question":"学校のメリット、私もこれは学校のホームページでトップページに載っておりまして、そこから拝見しましたが、たしかオープンキャンパスですとか、そちらに参加すると、受験料の半額免除みたいなものも書かれておりまして、そこからまた中に入っていくと、学費の免除といいますか、卒業後３年間、区の施設で働くと、そこの学費が免除されるということで、こちらは少し詳しくお知らせいただけますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"学校の学費ですが、２年間で約１８０万円です。そのうち全授業料に当たる１４０万円を借り受けできる制度となっております。卒業後、区の指定する施設で３年以上、介護業務に従事すると、返済が免除される仕組みとなっております。","voiceIndex":111,"id":"exchange-047"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。質の高い人材を育成・定着させるため、介護福祉士実務者研修、介護職員初任者研修等の受講に要した費用を助成しておりますが、こちらの実績、受講者数などをお知らせください。","respondent":"菅野高齢者福祉課長","answer":"１人当たり上限８万円となっておりまして、実績としましては、令和２年度３３人、令和３年度５２人、令和４年度９６人と着実に実績を上げているところです。","voiceIndex":113,"id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"本当に年々増加しておりますので、こちらもまた周知、拡充をお願いしたいと思います。人材不足の問題について、解決するための対策として、今後の介護職員の人材の確保、育成、拡充のためにも、福祉人材確保定着事業の取組をさらに進めていただけますようお願いをして、こちらについても国の人数にはなりますが、区の今後の取組がありましたら、お聞かせ願えますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"区におきましては、今のところ、大きな危機的な状況までには至っていないというところではあるのですけれども、そうは申し上げましても、訪問介護事業者等を中心に、なかなか人材の確保が難しいとか、人材派遣に頼らざるを得ないとか、そういった状況も聞いておりますので、今後。","voiceIndex":115,"id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日もよろしくお願いいたします。２２７ページの福祉計画課のほうの高齢者安否確認事業の中にあります救急代理通報システムですが、こちらはいつから始まった事業か、また、近年の設置件数と、こちらの要望を受けまして緊急出動の件数についてお伺いいたします。","respondent":"東野福祉計画課長","answer":"現在、この消防庁型につきましては、平成１９年から新規の受付がなくなっておりまして、令和４年度には０人ということになっております。一方、救急代理通報システムですが、平成１２年度から開始しております。","voiceIndex":118,"id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"予想していたよりもはるかに多くの通報と、誤報の部分もあったとは思いますが、実際、到着して安心された方がいらっしゃると思います。こういった一人暮らしのご高齢の方の事業を、ご家族が帰省する時期に発行する広報紙などに、タイミングをもって載せたりして、品川区外のご家族の方の目に触れたり、お知らせする方法があってもいいのではないかと思いますが、いかがでしょうか。","respondent":"東野福祉計画課長","answer":"現在、相談申請につきましては、在宅介護支援センターですとか、支え愛・ほっとステーションで受けるような形になっておりますので、その周知方法につきましても、拡大に向けて検討してまいりたいと思います。","voiceIndex":120,"id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"高齢者福祉課のほうの高齢者安否確認事業で、自動消火装置の設置と外出同行支援についてお聞きいたします。自動消火装置の給付ですが、事業評価を拝見いたしますと、実績が、近年ですと、令和２年度、令和３年度は１件ずつで、令和４年度は０件だったようですが、今年度も申請はないのでしょうか。どういったアシストで、どれぐらいの利用があるのか、現状をお聞かせください。","respondent":"菅野高齢者福祉課長","answer":"実績としましては、令和４年度は２０６件、令和３年度は２０７件ということで、多くの方が外出同行支援の援助を受けていると認識しているところです。","voiceIndex":122,"id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"自動消火装置のほうは、今の環境によりますと、必要性の低下ということが分かりました。ですが、こちらは、やはり火災や命に関わることですので、今年度も０件ということでしたが、廃止する前に一度対象を広げて状況を確認するか、または廃止するのか、廃止の前によく検討してから決めていただけたらいいなと思います。次に、認知症高齢者支援事業についてお伺いいたします。","respondent":"川原高齢者地域支援課長","answer":"ミーティングセンターにつきましてのお尋ねです。こちらのミーティングセンターは、全国に先駆けて令和４年に都内で初めて実施いたしました。","voiceIndex":124,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"意見","question":"今まで認知症の方本人にケアの重点が当たっていましたが、家族の方も一緒に支える新しい取組ということで非常に期待しております。始まったばかりで試行錯誤などいろいろあるとは思いますが、八潮地区などもありますので、ぜひ高齢者のもどかしい思い……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-054"},{"speaker":"山本委員","kind":"質問","question":"本日もよろしくお願いいたします。ほかの委員からもご質問がありましたが、私からは、２４９ページの高齢者向けパソコン・スマホ教室について伺います。","respondent":"川原高齢者地域支援課長","answer":"こちらは令和４年８月から令和５年３月までの年間で、教室は９６回、参加人数２０３名、そして、よろず相談のほうは、実施回数１４４回、延べ人数で７８６名の方にご参加いただいております。","voiceIndex":128,"id":"exchange-055"},{"speaker":"山本委員","kind":"質問","question":"８か月ということは、年間にすると、スマホ教室は約３００名参加しており、よろず相談は、年間約１,２００名が利用しているということですね。民間事業者に委託をされているとのことですけれども、スマホ教室とよろず相談、それぞれアンケートなどで利用者満足度や理解度は把握されておりますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"利用者、参加者に対しての理解度、満足度についてのご質問です。こちらは、１コース、月４回実施しているような形ですが、毎回受講者のアンケートを紙でいただいているような状況です。","voiceIndex":130,"id":"exchange-056"},{"speaker":"山本委員","kind":"質問","question":"利用者が満足し、スマホの習熟につながっているということを理解いたしました。とてもよいことだと思います。スマホ教室とよろず相談ですが、利用者の方の相関関係はありますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"教室と相談の相関関係はあるかというご質問にお答えいたします。こちらは教室と相談のつながりがございまして、同じ会場で午前中に教室を実施し、午後に相談を実施しています。","voiceIndex":132,"id":"exchange-057"},{"speaker":"山本委員","kind":"質問","question":"一方で、品川区内において、高齢者でスマホを持っていない方がどれぐらいいるかということを考えてみますと、まず、６０歳以上の方が約１０万人いらっしゃいます。この９,０００人が初めの一歩を踏み出すためのスマホ教室を受講するには、今の年間３００人のペースだと３０年かかります。スマホ教室の年間開催数を増やすことは具体的に計画されていらっしゃいますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"教室は、令和４年度は３か所で実施をしていたのですが、引き続き増やしていきたいと思います。","voiceIndex":134,"id":"exchange-058"},{"speaker":"山本委員","kind":"提案","question":"今年度に入って１教室増やされたと認識しておりまして、そうすると、年間約４００人ぐらいと考えております。開催場所を現在の５か所から１０か所に増やし、教室開催数を増やすというアプローチが考えられます。その文脈において、スマホ教室とよろず相談を拡充し、品川区のデジタル化加速につながるよう、提案、要望をさせていただきまして、私の質問を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"福祉の聡、やなぎさわ聡です。初日は介護職員の当事者として、２日目はデートＤＶの被害者の当事者として、今日は介護事業者の当事者としてお話しします。２４５ページの緊急介護職員確保についてです。時間があれば、４９５ページの運動系介護予防事業もお願いします。来年、２０２４年に介護報酬の改定がありますが、品川区として、総合事業について、何か報酬の見直し等を行うご予定はありますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"以前から総合事業については、区のほうで実情に応じて決めるというふうに金額設定しておりますので、介護報酬に連動して決めしています。その旨につきましては、介護報酬の結果を見ながら、区としても検討していきたいと考えているところです。","voiceIndex":138,"id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはり物価高もすごい、全事業所といいますか、全ての業界でそうですけれども、特に介護事業所、例えば送迎のあるサービスなどは、ガソリン代も物すごく高騰しています。物価高もありまして、そういった状況で、介護報酬を上げていただかないと、ただでさえ運営の厳しい介護事業所は、さらに疲弊してしまうと思いますので、そういったことはしっかりと考慮に入れていただけるということでよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"介護報酬につきましては、国の改定の動向を見するのですけれども、区が独自に決められると申し上げましても、やはり給付と負担の関係というところで、そこが上がると介護保険料も上がってしまうという、そういった悩ましいところもありますので。","voiceIndex":140,"id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"２０１５年に総合事業が始まって、介護事業所の収入が、その時点で１０％から２０％ぐらい下がったのです。ですので、その辺はしっかりと考慮してお考えいただきたいというふうに思います。それと、先ほど、ほかの委員から品川介護福祉専門学校の１４０万円は、区の指定する施設で３年間働けば免除になりますというお話がありましたけれども、区の指定する施設というのは、どういった条件でしょうか。","respondent":"菅野高齢者福祉課長","answer":"２点目の介護福祉専門学校の就学資金の指定の場所につきましては、こちらは、かねてより、先ほども社会福祉協議会が設立し、区と区内社会福祉法人等がバックアップしている運営だとお話をさせていただいたのですけれども。","voiceIndex":142,"id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"利益ではないのです。人材不足の面でいうと、６月の議会において、松永議員が同様の質問をしたときに、福祉部長は、品川区で介護人材の不足の認識はないとおっしゃいました。何か、例えば家賃の補助をするとか、それは介護職員に対してですけれども、介護報酬を増やすということが介護事業者の支援にもつながりますし、そういった両面での支援を、ぜひ私は要望したい。ということで、よろしくお願いします。","respondent":"菅野高齢者福祉課長","answer":"保険者としましては、介護サービスが安定的に提供できることが責務だと考えていますので、その上では、やはり介護人材の不足を、そういった事態に、危機的な状況に陥らないように、区としてはアンテナを張りながら。","voiceIndex":144,"id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"つけ加えておくと、やはり、この介護保険制度自体が２０００年ちょうどから始まって、今、２３年たちました。ですので、今の低賃金、重労働という介護職員の現場は、かなり不釣り合いな状況になってきているというところも、ぜひ現状を知っていただいて、介護職員は本当に大事な存在であり、そして、本当にスキルを持って仕事をしている、そういった方も多いことを認識してほしい。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-064"},{"speaker":"つる委員","kind":"質問","question":"２２７ページ、重層的支援体制整備検討経費、２４９ページ、高齢者多世代交流支援施設運営費、２５５ページ、児童センター運営費、２５７ページ、すまいるスクール運営費について伺っていきたいと思います。重層的支援体制整備事業ですが、先ほど、午前中の質疑でもありました。","respondent":"東野福祉計画課長","answer":"区でやっている事業、それから民間でやっている事業、ＮＰＯ等が行っているもの、そういったものを有機的に結びつけることで重層的支援体制を図っていきたいということで、１つの核ということでの位置づけだということでお話をさせていただきました。","voiceIndex":148,"id":"exchange-065"},{"speaker":"つる委員","kind":"質問・要望","question":"地域包括ケアシステムの当時から、２０２０年９月の第１回定例会から、この重層的支援体制については継続的に推進をしてきたわけでありますけれども、そうした議論の中で、品川区の体制としては、どうとっていくのかというところでは、いろいろな先行自治体の事例もこれまで質疑の中で確認をしながら、例えば、品川区、各所管課に、いわゆるＴ字型の職員を配置したりして、いわゆる核、本庁であれば。","respondent":"東野福祉計画課長","answer":"重層的支援体制整備を進める中におきまして、先ほど来、お話ししています支え愛・ほっとステーション、また、地域での、例えば在宅介護支援センターですとか、庁内でいくと、暮らし・しごと応援センター。","voiceIndex":150,"id":"exchange-066"},{"speaker":"つる委員","kind":"提案","question":"これについては、２０２１年の第３回定例会で、自民党のせりざわ委員が既にもう提案をされていて、その当時、本会議の質問でも言いましたが、いろいろ機能だとか、考え方とか、ゲームに対する捉え方とか、そういう時代の状況もあって、なかなか自治体としての捉え方がまだまだ未知数なところがあった中で、２年たって、今回は一定程度のご答弁をこれまでは福祉部門からいただいてきたのです。","respondent":"藤村子ども育成課長","answer":"こちらは、子ども育成課としては、どういったことができるかというところを検討していますけれども、具体的には、東中延児童センターで、今、平塚橋ゆうゆうプラザにお話をしているところでございまして、ゲームを使って高齢者の方と交流していくというところで。","voiceIndex":152,"id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、日常的な交流は非常に難しくて、昔であれば、銭湯だとか、公園も含めてですけれども、多世代の人たちが本当に交流していたという風景が、なかなか最近の品川区でも見られなくなってきた中では、こういう１つのｅスポーツというものをきっかけにした交流は非常に大切なのかと、これが先ほど前段で確認させていただいた重層、孤独・孤立の解消にもつながっていくのかなというふうに思いますので。","respondent":"藤村子ども育成課長","answer":"続きまして、仕出し弁当ですけれども、第一日野小学校で８月に１０日間試行実施したところでアンケート等をとらせていただきました。","voiceIndex":154,"id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、２４５ページ、２７７ページなどに書かれている、いわゆる保育士や介護士の方々の待遇改善などについてお聞かせください。それと、２９１ページ、システム構築、保守経費についてお伺いします。初めに、保育士、介護士の皆様の離職について見解をお聞かせいただければと思います。よろしくお願いします。","respondent":"石井保育支援課長、菅野高齢者福祉課長","answer":"保育現場ですと、結構ジェネレーションギャップみたいなものがあって、保育観の違いのぶつかりですとか、そういったところで悩みを持っていらっしゃる保育士もいらっしゃいますし。理由としましては、例えば、今も保育支援課長が申し上げましたが、やはり家族の介護だったりとか、職場での人間関係、あとは、ほかの分野でやりたいことがあるということで辞めていくなどの理由も聞いております。","voiceIndex":158,"id":"exchange-069"},{"speaker":"石田（し）委員","kind":"意見","question":"離職の理由として、介護士と保育士の離職の理由が実は似ていて、一番初めは正に人間関係だそうです。もう１つが、やはり給料が安い。もう１つが、いわゆる仕事の内容だったり量。この３つがそれぞれの離職理由として挙げられている。やはり給料が低いというのは、これは何とか行政ができる１つの対策になるのかと。これは介護、保育だけではなくて、３０年間、日本の給料は世界から見ても上がっていない。","respondent":"石井保育支援課長、菅野高齢者福祉課長","answer":"保育士の給料が上がっていくことは非常に大事なことだと考えています。ただ、民間事業者はそれぞれ様々やっていますし、例えば、今ちょうど国のほうでも子ども・子育て支援制度に関しての公定価格の見える化の検討をしています。業務改善をすることによって、少しでも負担を軽くするということにフォーカスしますと、例えば、ＩＣＴの見守りシステムの導入だったり、あとは、処遇改善加算が昨年１０月からあったりしたのですけれども。","voiceIndex":161,"id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"国の動向を見ていただいて、もちろんなのですけれども、区がどこまで本気で保育士や介護士に対して支援ができるのかということが大事であって、例えば、補助があまりよくないのではないかみたいな話も出ていたけれども、では、どうするのですかと。そこは本気で、ぜひ対策を打っていただきたいと。約１,０００万円ぐらい。なぜこのようにシステムを改修しないとできない給付なのですか。お聞かせください。","respondent":"豊嶋生活福祉課長","answer":"今回の決算書に書かれております保守費等々につきましては、令和３年度以降開始されました臨時給付金について、それらに対応するために、保守、それからシステムの構築、データの利用料、あとは家計急変世帯という少し特殊なシステムを構築しないと。","voiceIndex":164,"id":"exchange-071"},{"speaker":"西村委員","kind":"質問・要望","question":"２４９ページ、高齢者向けパソコン・スマホ教室、２５７ページ、児童相談所移管推進事業、４９７ページ、介護保険特別会計より介護予防による地域づくり推進事業と、時間が許せば、栄養改善事業について伺ってまいります。ハード面、建物内で、区独自の取組としてこだわっている点があれば、改めてお聞かせいただきたいと思います。併せて、現状の取組をお聞かせください。","respondent":"長谷川児童相談所開設準備課長","answer":"建物内での区独自の取組ですけれども、様々な部分で特色があると考えております。例えば、被害確認の面接を実施できる環境が整っており、ここでモニター室を活用しながら子どもの様子を確認することで二次被害を防いでまいります。","voiceIndex":167,"id":"exchange-072"},{"speaker":"西村委員","kind":"質問","question":"様々に想定して準備していただいていることがよく分かるのですが、今おっしゃった二次被害というのは、どのようなことが考えられるのか教えてください。","respondent":"長谷川児童相談所開設準備課長","answer":"被害を受けた子どもが大人から何度も何度も同じことを聞かれることで心の傷を深めてしまうことを防ぐことを目的に、警察や検察と児童相談所が連携し、一度きりの面接で終了することを基本に実施いたします。","voiceIndex":169,"id":"exchange-073"},{"speaker":"西村委員","kind":"意見","question":"私のこれまでの知識や経験を超えるぐらい、十分に配慮していただいていることがよく分かります。決算書に、太陽光の費用が記載されておりまして、停電時、災害時、有効な活用ができるように、こういった活用を想定して蓄電池や太陽光を設置していただいていると思うのですが、改めてどのような場合を想定されているかお聞かせください。","respondent":"小林施設整備課長","answer":"特に、本施設につきましては、事業継続という観点でいきますと、ご案内のありました太陽光であったりとか、蓄電池、また、この施設につきましては、発電機も設置をしているところでございまして、この３つが稼働することによりまして、一時保護所のトイレであったり。","voiceIndex":171,"id":"exchange-074"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、一般質問でも質問させていただいたのですが、子どもの意見聴取等の仕組みの整備が厚生労働省より求められております。区では、事業として制度を位置づけて準備していただいていると思いますけれども、このアドボケイトの準備状況について伺わせてください。","respondent":"長谷川児童相談所開設準備課長","answer":"この支援員をアドボケイターと呼びますが、このアドボケイターがバックアップ組織に意見を報告し、バックアップ組織から児童相談所等へフィードバックすることで、子どもの意見を考慮した支援の実現を目指して、今、検討を進めているところです。","voiceIndex":173,"id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"国の方向性にのっとりまして、念入りに準備してくださっていることが課長のお話を伺っていると本当によく伝わってくるのですけれども、この子ども意見表明支援員がうまく機能すれば、子どもたちの心の声を受け止める体制ができますので、正に声なき声を届けていけると思いますし、以前、打合せの際に課長が、地域の子どもは品川区で守るとおっしゃった言葉が、私も忘れられずにおります。","respondent":"長谷川児童相談所開設準備課長","answer":"現在、他自治体での派遣により育成を図っておりますが、区児童相談所が開設されましたら、ペアレント・トレーニングをはじめとするあらゆる心理手法を用いまして、子どもに寄り添った対応をしていきたいと考えております。","voiceIndex":175,"id":"exchange-076"},{"speaker":"西村委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。引き続き、先ほど来、委員からも様々質問がありますけれども、「はじめてのスマホ体験教室・スマホよろず相談」に関して、私もニーズの高まりを大変実感しておりまして、こちらについて伺ってまいりたいと思います。どのように受講者の方に伝えているのか、改めてお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"こちらは、１コース４回となっておりまして、まず１回目は、初めて手にとる方もいらっしゃいますので、デモ機をお貸出して、電源の入れ方から始まります。初歩の電源の入れ方であるとか、そういったところを第１回のコースで２時間じっくりとかけて学んでいただきます。","voiceIndex":177,"id":"exchange-077"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど、ゲームという質問もありました。各自治体も新しい取組をこぞってトライしておりますので、品川区の高齢者介護予防の一環として、様々新しい取組もトライしていただきたいと考えています。このゲームのような新しいコンテンツの拡充ですとか、そういった取組について、何か検討されていることがあれば、お聞かせください。","respondent":"川原高齢者地域支援課長","answer":"ゲームを用いたアプリなどの取組状況に対するご質問です。昨年度、令和５年３月に、１回限りの試行的体験事業ということで、はじめてのゲームアプリ体験を実施したところです。","voiceIndex":179,"id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"ゲームを交えると交流しやすいということもありますし、囲碁のゲームも高齢者の方の間で大変人気だということを伺っております。最後に、介護予防のための通いの場について伺ってまいりたいと思います。介護予防体操、フレイル、認知機能活性化講座など、区民目線で独自の取組を行っていただいていますが、改めて今年度の実績と取組、また、課題についても併せて伺えればと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらは、介護予防による地域づくりの推進ということで、区内法人に勤務するリハビリテーション専門職、いわゆる理学療法士などの専門職の派遣を出張講座という形で介護予防の講座に講師として派遣をして、住民主体による通いの場によるモデル実施を図っているものです。","voiceIndex":181,"id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"通いの場は、５人以上集まれば講師が出向いてくださると、そういうものだと思うのですけれども、なかなか自然発生的なグループをつくっていくというのは難しいのだろうなというふうに課題として思っておりまして、「高齢者クラブに参加しているだけで、なんだかんだ忙しいのよ」と高齢者の方々が言ってくださることがすごくうれしいので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"２４５ページ、福祉人材確保・定着事業に関してお伺いしたいと思います。平成１２年から介護保険制度が始まりまして、品川区は、それ以前から先進的な取組として介護事業に取り組んでまいりました。","respondent":"菅野高齢者福祉課長","answer":"これは区内の事業者だけではなく、国全体の問題として、国の審議会等でも議論されている部分ではありますので、そういったところは国の動き等も見ながら、もちろん区内の事業者の声を聞きながら、決して足りているとか、そういった楽観的なことを言わずに、今のところ。","voiceIndex":185,"id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときに実務者研修とか初任者研修とか、介護福祉士の資格を取るとかの道はありますけれども、ケアマネジャーの資格を取るという視点も、将来に向けてはあると分かれば、また将来のことも安心感を持っていただけるので、品川区の介護施設にどんどん入ってくることにつながる１つの施策ではないかと私は思っているのですが、そういったキャリアアップの観点からの取組をお聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ただ、区民限定とか、その辺りの対象者についても、今後は現場の声も聞きながら検証していきたいと思っているところです。さらに、ケアマネージャーとか、キャリアアップについての助成についても検討していかなければいけないと感じているところです。","voiceIndex":187,"id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、２２９ページの障害者福祉施設等整備費、それから２３３ページの自立支援給付事務、障害者関係は特に医療的ケア児者について伺いたいと思います。品川区地域自立支援協議会や障害者差別解消支援地域協議会は、そういうものがきちんと出ていますので、それと同様に、ホームページへの掲載もしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"この３０人という数字なのですが、品川区の当課で行っております在宅レスパイト事業および障害児支援の利用者のうち医療的ケアを要する人数ということになっております。年内に１回目は開催予定で進めております。委員がご指摘くださった議事要旨のホームページ掲載ですけれども、大変申し訳ございません。遅くなっておりますが、速やかに掲載をします。","voiceIndex":191,"id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この医療的ケアの、様々この会議の中でも課題が出されましたけれども、本当に改善が求められるところですので、今回の１回だけでなく、されていくということなので、ぜひ充実をさせていただきたいと思います。その人数が分からないと、どういう形で取り組むかということもなかなか難しいと思いますので、できるところでできる限りの人数の把握はお願いしておきたいと思います。これはありがとうございました。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"人工呼吸器だからということではないと思うのですが、それぞれの病院の判断、あるいはご本人の健康状況によって、やはり医師の判断によりなかなか難しい部分があるですので、それは今後も品川区内の医療ショートを。呼吸器をつけた方の受入対応の件ですが、もちろん区としましても、障害の重度化、高齢化、そして医療的ケアが必要な方も地域で安心して暮らせる支援体制の整備が必要ということは認識しております。","voiceIndex":194,"id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"よろしくお願いします。グループホームも医療的ケアの必要な方が入れるグループホームはありません。なぜ品川区は高校卒業までとしているのか、ぜひ高校を卒業した後も、保護者、家族の就労支援とか、障害者の方々を日常的に介護している家族の一時的な休息を確保するというためにも、利用できるように対象年齢の拡大をしていただきたいと思うのですが、いかがでしょうか。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"今後、中・重度の方を受け入れる障害者グループホームとして、委員もおっしゃった出石つばさの家が令和６年４月１日開設予定、そして令和７年度中に小山七丁目障害者グループホームを開設予定です。私からは、日中一時支援についてのご質問にお答え申し上げます。現在、品川区では、日中一時支援ではなく、生活介護の延長支援で対応しています。","voiceIndex":197,"id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いつも介護保険の計画を立てるときに、３年間でどれだけ取り崩すか、そして、その分を保険料の引下げに使いますということで方向を出して保険料を決めていくということになっていたと思うのですけれども、それが幾らぐらい取り崩すという計画だったのか、それなのに、令和４年度は１８億円を超えましたので、逆に増えてしまっているのですけれども、なぜこういう形で。","respondent":"菅野高齢者福祉課長","answer":"その後、現在の基金は１８億円になっておりますが、少し基金が積み上がっているという部分につきましては、この法則でいくと、例えば、今年度、足りなくなったら、それを少し繰り入れるとか、そういった形で３年間運用する見込みとなっておりますので。","voiceIndex":200,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが１８億円まで増えているということなので、その理由がどうなのかというふうなことで伺ったのですけれども、今の説明ではよく分からない。それでいよいよ９期がまた始まりますので、この積み上がった基金は、保険料の引下げにぜひとも活用していただきたいということで、意見として申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-087"},{"speaker":"こんの委員","kind":"質問","question":"私からは、順不同でまいります。２４７ページの高齢者社会参加支援と、高齢者外出習慣化事業、もう１つが、２２７ページ、地域福祉推進費からお伺いしたいと思います。高齢者の社会参加、外出習慣化促進の観点から、食事を通した交流の場についてお聞きしていきたいと思います。そこで、まず高齢者の孤食について、区の見解をお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"介護予防、フレイル予防につきましては、１つとしても、やはり低栄養というところがフレイルにつながっていくということで懸念しておりまして、総合事業でも栄養改善事業であるとか、あとは、一般介護予防事業の中でも、いろいろ食の、クッキングの教室など。","voiceIndex":204,"id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"シニア食堂というものはできないでしょうかというお声がありました。認知度は低く、２３区内でも事例は聞いたことはありません。こうしたものが活用できるのであれば、品川区でも考えていけるのかなと、このように考えるところですけれども、シニア食堂についてのご見解と、また東京都のこの事業について、お分かりになれば、少し概要などをお知らせいただけますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"シルバー食堂につきましては、今年度限りの補助事業となるのか、また来年度も引き続き実施するのかですとか、引き続き調査をしてまいりたいというふうに、情報収集も含めて行ってまいります。","voiceIndex":206,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご紹介ありがとうございました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"確認","question":"脱会をされて、「なぜですか」と言ったら、「あんなの、入っていても何の役にも立たない。そうなったときに、先ほど、法的な支援をしていくというお話もあったのだけれども、これはやっていくときに、ポイントで何かやったほうがいいのかなと思っていて、そういう意味では、私は、安否確認については非常にいいのかなと思っています。来なかった人のこととか。早い人は１年で６回とか、７回来るらしい。","respondent":"川原高齢者地域支援課長","answer":"全国的にもやはりクラブの減少と会員の減少が課題となっているところで、今後、全国老人クラブ連合会、全老連による実態調査が実施される予定となっているということを伺っておりまして、その調査結果を分析・検討されて、全老連より提案、また提言が図られるです。","voiceIndex":210,"id":"exchange-091"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私より１０個、１５個ぐらい上の人でも、そう考えている人は結構いる。委託だったらそれはきちんといろいろできるけれども、再任用だ、会計年度任用職員が行ったりすると、勘違いしてしまうのではないかと思っていて、そういう事業はないほうがいいと思っているのだけれども、なかったら、ごめんなさい、そこら辺のところが何となくあるような気がしてならなくて、そこら辺のところが分かれば教えてほしい。","respondent":"菅野高齢者福祉課長","answer":"高齢者福祉課においての会計年度任用職員は、二十五、六人いるのですけれども、高齢者福祉課においての会計年度任用職員は介護認定の調査員たちで、正規の職員が介護認定の調査の訪問に行くときの割り付け等をさせていただいたりとかというところで。","voiceIndex":212,"id":"exchange-092"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私の勘違いかもしれないので、ぜひ私も勉強しますけれども、そういうことがあったほうが、私は正規職員の方がいて、それはしっかりそういう政策をどういうふうにしていくのだ、これからもこういうふうにしていくのだということは、そこはそういう形でやっていただきたいと思っています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-093"},{"speaker":"木村委員","kind":"確認","question":"座ったまま、また今日もよろしくお願いします。２３１ページの障害者まつりについてお伺いいたしますけれども、確認ですが、この９月に中小企業センターで行われた「ふくしまつり」のことだと思いますけれども、これと一緒だということでよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"委員のおっしゃるとおり、９月１６日に中小企業センターで行われたおまつりが「ふくしまつり」、障害者まつりと同じものです。","voiceIndex":216,"id":"exchange-094"},{"speaker":"木村委員","kind":"質問","question":"これはなぜ名前が違うのでしょうか。私が理解できないので、それが分かればお聞かせください。","respondent":"松山障害者支援課長","answer":"「障害者まつり」と「レクリエーション」というものが２つあるのですけれども、それをひっくるめて「ふくしまつり」ということで、ふくしまつりについては、実行委員会形式で行っておりますので、通称として「ふくしまつり」というふうに呼ばせていただいております。","voiceIndex":218,"id":"exchange-095"},{"speaker":"木村委員","kind":"質問・要望","question":"その目的の下、行われた障害者まつりは、共生社会を目指す大事なまつりであると思っています。つまり、障害者まつり当日は、多くの方々が参加をして、そして大盛況であったということを聞いております。どれぐらいの参加者があったのかお聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"参加人数についてです。延べで１,８７０人の方にご来場いただきました。","voiceIndex":220,"id":"exchange-096"},{"speaker":"木村委員","kind":"意見","question":"１,８００人余の多くの方々に気にかけていただいているということだけでも大変うれしいことであります。大変ありがたいことだと思っています。多くの方々が参加されていましたけれども、けがやトラブル等はなかったのかどうか、それもお聞かせください。","respondent":"松山障害者支援課長","answer":"ふくしまつりも４年ぶりの現地開催ということで、皆さん、事務局側としては、４年ぶりなので、何かということで、非常に職員も慎重に、熱中症対策ですとか、いろいろな方がいらっしゃるのでと思って、いろいろ配慮を重ねていたのですけれども、当日は何のトラブルも起きずに。","voiceIndex":222,"id":"exchange-097"},{"speaker":"木村委員","kind":"質問","question":"これは当日何もなかったということで最高ですから、これからもまた安全に行うことを願っています。たくさんの区民が参加して楽しまれたことであったふくしまつりでしたけれども、実行委員会形式で行っていると思いますが、どのような団体が、何団体ぐらいが参加された実行委員会をつくっているのでしょうか。これもお聞かせください。","respondent":"松山障害者支援課長","answer":"実行委員会の団体数です。３２団体の方が参加されました。","voiceIndex":224,"id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"私も今、松葉杖をついて歩いている状況でありますから、このような気持ちも分かりますし、皆さんと共にまた頑張っていきたいと思っています。そして、それだけ多くの団体が参加をされているふくしまつりをつくっているのは、大変なご苦労であったと思いますけれども、実行委員として参加された団体の声が何かあれば、お聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"実行委員として参加された団体の声ですが、皆さん、やはり４年ぶりの現地開催ということで、実行委員の方々も久しぶりで、「どうやったか忘れてしまったよ」というような声、あるいは、忘れたところで、皆さん、補ってやっていこうよというような状況でした。","voiceIndex":226,"id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"障害を持った団体、方々、やはり多くの方々と力を合わせながらやっていくことが一番だと思いますから、ぜひ行政として音頭をとっていただいて、みんなが元気に無事に過ごせることをぜひ願っておりますが、その点を最後に力強くお聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"区としても、障害者とご家族が、区の施設や社会福祉協議会、ボランティア団体と共に、区民との交流、親睦を図って、障害者の方への理解を深めていただくとともに、やはり障害のある人もない人も共に楽しみ、ふれあう場として非常に大事なふくしまつりだと考えていますので。","voiceIndex":228,"id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"そういう点において、私もいろいろな目で見られていると思いますけれども、そういうことがないように、本当に一般区民も、また障害をお持ちになっている区民も、何の差別もないわけでありますから、そういう点についても十二分に注意をしていただいて、これからも頑張っていただきたいと思います。作品展に出展される作品の数、出展者の数なども教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"令和４年度ですけれども、人数としては５６６人の方が出展に関わりました。出展された数としては、１１３作品です。最近は、結構、各団体や特別支援学校で合同で皆さんで作るような大きな作品ですとか、力を合わせたようなものが多くなってあります。","voiceIndex":230,"id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"そういう点につきまして、私は何か特別な才能を持ったそういう方もたくさんいらっしゃると思いますから、そういう方々に対して、また皆さんの力を貸していただきたいと思います。最後に、手話理解促進についてですけれども、令和４年度から心身障害者福祉会館の手話講習会に加えて、区職員、事業者、子ども、また区民向けの手話講座を行ってきたと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"２７３ページのぷりすくーる西五反田についてお聞きします。このぷりすくーるは、認定こども園にするということで、ＮＰＯ法人から福栄会に運営が変わっておりますが、いまだに認定こども園にはなっておりません。これはいろいろな理由があって、スペースの問題、園庭の問題であるとか、いろいろな課題があるのです。その課題をどう解決して認定こども園にしていくのか、そのスケジュールを教えてください。","respondent":"立木保育課長","answer":"こうしたところの課題を解決するために、今、検討を進めている最中でして、明確なスケジュールは、今後の予定のところはお示しできないのですけれども、隣の区立保育園もありますので、一体的なところも考えながら、今後検討を進めていくという。","voiceIndex":235,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"園庭のスペースが足りないということが一番大きいと思うのですが、やはり今おっしゃったように、隣には西五反田保育園がありますので、今後どういうふうにしていくのかというのは、総合的に考えていただきたいと思います。でも、忘れてはいけないのは、子どもの利益とは何ですか、親子の関係で大切なのは何ですか、それを念頭に入れて考えていただきたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"ただ、諸般の事情によって、やはりどうしても就労しないといけないというような事情もある中で、そこのところは病児保育という制度を使って、親御さんに代わってプロの保育士、看護師がきちんとお子さんの育ちを保障する、そういうような考え方の中で、今。","voiceIndex":237,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"熱が出たときぐらい、調子が悪くなったときぐらい、会社を正々堂々と休める、そういう社会を目指すべきではないでしょうかと私は思っております。あれをやります、これをやります、それをやりますはいいかもしれないけれども、根底に置いているのは、子どもの利益とは何でしょうかということが一番大切なことだと思いますので、それを念頭に置いて行っていただきたいと思います。課題は何でしょうか。","respondent":"藤村子ども育成課長","answer":"今回のすまいるスクール仕出し弁当試行ということで８月にやらせていただいたというところですが、課題としては、今回、お弁当の業者が、例えば、リユース容器を使った業者ではなかったので、ごみの持ち帰りですとか。","voiceIndex":239,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"これも子どもの利益を考えたときに、どういう方法がいいのかというスタートでなければいけないと私は強く思っています。そして、改めて、すまいるスクールの役割とは何でしょうか。歴史的な経過があります。以前は、全児童対策と学童保育が品川区にはありました。それをなくしてすまいるスクールになったのです。それはどういう理由なのか、そして、すまいるスクールの役割は何でしょうか。","respondent":"藤村子ども育成課長","answer":"すまいるスクールは、全児童に対する放課後対策として、放課後子ども教室と学童クラブの両面の要素を持つものとして始まったものということで、全小学校に放課後や土曜日、長期休み中に学校施設を利用して、学習、遊び、スポーツなど。","voiceIndex":241,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"すまいるスクールが始まる前に、品川区は、全児童対策と学童保育が併設だったのです。それまでは学童保育をやっていて、児童センターが中心だったのです。それは保育という観点でやっていたのです。就労する親たちのための保育に欠けるということから、これは厚生労働省管轄のものでやっていたのです。そういう仕組みになっているのですが、品川区はなぜ今の形態にしたのでしょうか。目的は何でしょうか。","respondent":"藤村子ども育成課長","answer":"保護者の方々が自由にお預けして、子どもの育成というところで、こういった観点が一番というところで、この今のすまいるスクールの形になったかと考えております。","voiceIndex":243,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"保育ということが強くなってきた。だから、夜も７時まで預けられるようになってきたという経緯はあります。保育の中で親と一緒に育てるというところが、やはり学校、教育委員会、ＰＴＡはあるけれども、それよりももっとすまいるスクールというのは、保護者の方々と一緒に子どもを見守るということをぜひ進めていただきたいと考えていますが、これからのすまいるスクールの在り方についてお答えください。","respondent":"藤村子ども育成課長","answer":"これからのすまいるスクールの在り方としては、保護者の方の教育というところももちろんですけれども、子どもにとって通いやすいですとか、楽しんでいただけるというようなすまいるスクールを目指してやっていきたいと思います。","voiceIndex":245,"id":"exchange-108"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、成果報告書３１ページ、福祉人材確保・定着事業、３２ページの認知症高齢者支援事業、決算書２５５ページの児童センター運営費、順不同にて質問いたします。区内には２５の児童センターがあって、０歳児から１８歳のお子さんと保護者が利用できる施設となっています。要は、２つの施設で直営がなくなりました。これによって１人の館長が委託館を多く抱えているということはお聞きしております。","respondent":"藤村子ども育成課長","answer":"館長館の減少というところについてのご質問かと思います。本件につきましては、令和４年度に児童センターの在り方検討ということで、児童センターのニーズですとか、そういった総合的な調査を行ったところです。","voiceIndex":249,"id":"exchange-109"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"人材育成という部分においては、私の考えは、だから１３地域とこだわりを持っていた品川区の心意気というか、それは継続してほしかったなということが正直あります。平成６年なので随分お久しぶりな感じなのですけれども、やはり私は、個人的に、この児童指導職は増やしていくべきと思いますので、継続して頑張っていただきたいと思っています。この２つの事業の最近の利用率、そして利用数をお示しください。","respondent":"藤村子ども育成課長、立木保育課長","answer":"すくすく赤ちゃん訪問の事業ですけれども、こちらは保健センターの事業となっておりますが、対象が令和４年度ですと全体で３,４００人程度というところでした。保育園でのチャイルドステーション事業ですが、保育園も、チャイルドステーションとしては、授乳ですとか、トイレですとか、そういったことにお気軽に利用できるというところになっていまして。","voiceIndex":251,"id":"exchange-110"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そうすると、これは児童センターの区割りではなくて、どういった割合でこの事象が起こっているのか教えていただきたいのが１点。チャイルドステーションです。こういうすばらしい事業こそ、区でもっともっと力を入れて、例えば全部の中学校と一緒にやっていくとか、児童センターの負担もあるかもしれないですけれども、そういった事業の整理が必要かと思いますが、ご見解をお聞かせください。","respondent":"藤村子ども育成課長","answer":"準備投函のお話ですけれども、投函は地域センターの１３地区で区分して、児童センターがそれぞれ対応する館長館でやっているので、境目などだと少し離れたところが投函するというパターンはあるかもしれないのですが、というところです。","voiceIndex":254,"id":"exchange-111"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"センター割り、表札の話は、職員の方も実際におっしゃっていました。新規事業にそういう結びつけというのは、私は効果があると思うので、そういった意味でいろいろ取り組んでいただきたいと思っています。これは福祉部での視点とは違う角度で子どもや保護者を見守るために始まった事業かと思いますが、どのような事業で、どういう状況なのか、ご説明をお願いいたします。","respondent":"藤村子ども育成課長","answer":"こちらについては、２種類、父親の関係の事業がございまして、児童センター全館で実施している父親の子育て応援事業というものがまず１つです。もう１点が、３つの児童センターで開催している父親の親育ちワークショップというものがございまして、２つ事業があります。","voiceIndex":256,"id":"exchange-112"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要望を聞けば、すぐに活動に取り入れてくれたり、行っている児童センターがあまり多くないので、もっともっと拡充したいという、これは要望で終わります。すみません、時間がなくなったので、認知症支援事業について先にお聞きします。あれは本当にすばらしいです。もの忘れ検診もガイドブックがすばらしくなったので、どういう経緯であのすばらしいガイドブックができたのか、お伺いします。","respondent":"川原高齢者地域支援課長","answer":"オレンジフェスタの取組、ご参加、ご見学いただきましてありがとうございました。検診のガイドブックにつきましては、令和４年度新規事業として開始しましたので、そちらの検討も踏まえまして、お医者様の意見を取り入れて、さらに充実を図ったところです。","voiceIndex":258,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"２４７ページの高齢者活動支援事業から、２項目ほど確認をします。１つ目が、高齢者向けパソコン・スマホ教室、これはシート等で確認いたしまして、実施回数が前年度比３倍弱、また、参加人数も５倍弱というふうに数字を確認いたしました。行政コストのほうで表で見ますと、支出としては、委託料が４倍に増えた。続けまして、これは今年度から始まった事業の確認をさせていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"やはり皆様、地域の方のご意見を伺いますと、近所のほうが通いやすいというようなご意見もいただいたりとか、逆に、介護予防になるので、バスに乗って、自転車に乗って通うという元気な方もいらっしゃいますので。","voiceIndex":261,"id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"そういったところでは、シルバーセンターでは、今、実施しているほかには、五反田、西五反田、上大崎、南大井、ゆたか、小山、後地、南品川、西大井という各地域にシルバーセンターがあって、ゆうゆうプラザも４か所のうち３か所、平塚では行われていないですので、しっかり所管の中で、まずどこまで広げられるかチャレンジをしていただきたいというふうに思います。経過が分かりました。","respondent":"川原高齢者地域支援課長","answer":"やはり耳の聞こえに不具合を感じている人が少しでも早く補聴器を入手したいという思いは区としても感じてありますので、その辺りは、財政部門とも相談をしながら速やかに実施に向けて取り組んでまいりたいというふうに考えてあります。","voiceIndex":263,"id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"それぞれ大変前向きなご答弁をいただいたと思います。補聴器のほうは、一般質問、代表質問等でもずっとやっておりますけれども、ぜひ医師の方、また販売店と連携をして、そして何よりも今回購入をされた方々が、品川区のシステムで補聴器が生活の質の向上等に資するかどうか、そういう検証する仕組みの構築を引き続きしっかり行っていただいて、事業の拡充をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"２７６ページ、保育支援費のうちの区内私立保育園経費について、順序が逆になりましたが、２５７ページ、児童相談所、同じく、青少年育成事業。こちらは令和３年３月開設。当該保育園は、令和２年４月開園ですが、開設時の補助金等についての実績報告の段階で、品川区のチェック機能が働き、不備があれば、その段階で修正していたことがあったのでしょうか。それともなかったのでしょうか。お伺いします。","respondent":"石井保育支援課長","answer":"しなおおコスモ保育園に対する補助金受給の件です。もちろん開設に関する経費の補助金に関しましては、補助金の申請があった後、幾つか打ち返しをしながら経費の精査をした上で補助金の交付決定をしています。","voiceIndex":267,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"確認","question":"精査をして補助金を交付したというお答えでした。品川区は入っていなかったのですが、その報告書を取り寄せて、再確認を実施していれば、その方法を今どういうふうにして行っているか。していなかったら、していなかったで結構ですが、お伺いします。","respondent":"石井保育支援課長","answer":"本件報道等を受けまして、一度、文教委員会で報告をさせていただいてあります。今回、内装工事等々、厨房機器のほうで１つ疑義が生じているということで、現在、書類を精査している途中ですので、その中で、もし不正等がありましたら、返還請求等を行ってまいる所存です。","voiceIndex":269,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認しますと、最初に補助金等を交付したときにはオーケーだったと。","respondent":"石井保育支援課長","answer":"児童福祉法や子ども・子育て支援法に基づいた、いわゆる報告の聴取というふうなことで、今後、例えば、チェック機能を働かせるということもないわけではないのですけれども、そこについては切り分けて考えているところです。","voiceIndex":271,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"この事案は、１月にマスコミが報道し、１５回にわたって非常に詳細に報道されています。これらの施設に年に１回の監査を実施するとすれば、多大な時間と人員が必要と推測されます。ということで、来年度に向けて児童相談所を開設するわけですから、人事配置、そして予算編成の時期でもありますので、監査体制の充実をどのように考えていらっしゃるのか、具体的に体制整備の状況をお伺いします。","respondent":"立木保育課長","answer":"指導検査の担当は、今、保育課にありますので、お答えします。児童相談所設置市事務が移管されることに伴いまして、指導検査も大幅に増えることが確実になっております。","voiceIndex":273,"id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和４年度から整備をしてきているということですね。複雑な補助金の制度なので、先ほど言ったように、大変な時間や人員が必要なのですけれども、やはり行政の甘さがこういった形で他の自治体に出ていると思います。先ほど、令和４年度から増やしているということですが、令和５年度以降もそうやって整備、体制を強化していくところでしょうか。その点、お願いします。","respondent":"立木保育課長","answer":"区全体で考えなければいけないため一遍に増やすことがなかなか難しいので、毎年毎年体制を強化しながら、令和４年度、令和５年度、そして来年度という形で、今、増やしてきているところです。","voiceIndex":275,"id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"児童相談所に関連してですが、文教委員会でも少し確認させていただいたのですが、児童相談所開設を先行している８区で、措置費共同経理課を区政会館内に設置するということです。品川区も来年度ありますので、この措置費共同経理課について簡単にご説明いただいて、品川区では来年度予算にどのように反映させ、どれくらいの予算規模になるのでしょうか。","respondent":"長谷川児童相談所開設準備課長","answer":"先行８区では、第３回定例会に合わせて規約を提案しています。品川区におきましては、まだ根拠となる設置条例がありませんので規約には載せておりませんが、児童相談所設置条例を提案した後に、その規約の修正ということで、改めて提案をする予定となっています。","voiceIndex":277,"id":"exchange-122"},{"speaker":"松本委員","kind":"確認","question":"よろしくお願いします。私からは、２２７ページ、長寿お祝い事業、少し時間が間に合わないかもしれませんが、２５７ページのすまいるスクール運営費について伺います。長寿お祝い事業ですが、この事業の目的を改めて確認できればと考えています。","respondent":"東野福祉計画課長","answer":"直接本人または家族の方にお祝い金を手渡すことにより、所在確認、安否確認を行うという側面も持っているものです。社会福祉協議会も区と同様のお祝いをお渡しするということで、区と同じような形の事業を社会福祉協議会の事業として行っているものです。","voiceIndex":281,"id":"exchange-123"},{"speaker":"松本委員","kind":"確認","question":"これだけでなく、ほかにもあるので、さらにお伺いしていきたいのですけれども、かつては、傘寿の方にも配られていたというふうに議事録で確認いたしました。この平成３０年〔同日後刻に「令和元年」と発言訂正あり〕に廃止されたときの経緯と、あと、なかなかこういった事業を見直される場合には、反対意見もあったのではないかというふうに思いますが、この辺りの経緯をお伺いできればと思います。","respondent":"東野福祉計画課長","answer":"当時は、やはり本人とかご家族の方から、なぜなくなったのかというようなお問合せがあったという記録があります。こちらにつきましては、丁寧に説明し、ご理解いただいたということでの記録があります。","voiceIndex":283,"id":"exchange-124"},{"speaker":"松本委員","kind":"確認","question":"そうなってくると、政治判断のところもあったのかなです。すみません、先ほど、平成３０年と申し上げましたが、令和元年ということで訂正します。少し確認なのですが、これ、１０１歳以上というのは、１０１歳以上の方に毎年配られているということでよろしいでしょうか。","respondent":"東野福祉計画課長","answer":"１０１歳を超えている方につきましては、毎年配ってあります。","voiceIndex":285,"id":"exchange-125"},{"speaker":"松本委員","kind":"確認","question":"令和４年度の配布人数が３,５４１人で、前年度を確認すると、３００人ぐらい増えているかと思います。これは１割ぐらい増えているということです。これは一番ボリュームがあると思われる団塊の世代の方々が、まだそこまで達していないので、今後かなりの増え方をするのかなというふうに思うのですけれども、こちらは区としては今後の増え方をどのように考えていらっしゃいますでしょうか。","respondent":"東野福祉計画課長","answer":"品川区におきましても、７５歳以上の後期高齢者の人口が増えてきておりますので、この後も増えてくるというような見込みをとっております。","voiceIndex":287,"id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"今後も人口が増えるということは認識は共通しているかと思いますし、支える成人年齢の働いている方たちの人口も少し減っていくというふうな状況、これは東京都、品川区もいずれそうなっていくかと思いますけれども、あとは、社会福祉協議会とも重複しているということで、８８歳と９０歳の方たちについては２年ごと、９０歳と１００歳では１年、１００歳以上の方たちについては毎年ということなので。","respondent":"東野福祉計画課長","answer":"そういったところも含めまして、品川区としては、引き続き、この事業については続けていきたいと、またいろいろなお礼のお手紙ですとか、お電話もいただいているところですので、高齢者の方に向けて、安否確認も含めた事業として続けていきたいと考えているところです。","voiceIndex":289,"id":"exchange-127"},{"speaker":"松本委員","kind":"確認","question":"なかなかこれは決断が難しいところだと思うのですが、少し観点を変えて、先ほど、安否確認というところのお話があったかと思います。一方で、簡易書留で送っているというふうな情報もあるかと思いますが、これは今、どういうふうに送られているのでしょうか。","respondent":"東野福祉計画課長","answer":"実は、コロナ禍におきましては、直接お届けすることが非常に難しい状況ということを踏まえまして、郵送で簡易書留等を使ってお送りしています。","voiceIndex":291,"id":"exchange-128"},{"speaker":"松本委員","kind":"質問・要望","question":"令和５年度からは民生委員の方が伺われているということで、よかったのかなとは思うのですけれども、ただ一方で、安否確認に関しては、例えば、同じシニアの方でも、実際に家族の方がたくさんいらっしゃる方もいらっしゃれば、独居老人といわれる方もいらっしゃるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-129"},{"speaker":"藤原委員","kind":"質問","question":"２３０ページ、障害者支援費、２８５ページ、生活保護費。ただ、今日は民生費なので、福祉部についてお伺いしますが、まず、本庁舎入り口を入ったところ、障害者支援課、決算書を読むと、いろいろな項目がある中、あの人数でこれだけの事業をやられていて、本当に痛み入ります。課長、職員の方のメンタル面をどう支えているか教えてください。それで、課長、メンタル面をどう支えているか教えてください。","respondent":"松山障害者支援課長、豊嶋生活福祉課長","answer":"職員一同、本当に区民の方に対して、安定した丁寧な対応に努めているところです。その中でも係内、課内、チームワークを持ちまして、各係であれば、係長がその辺りをぎゅっと信頼関係の下にうまく指導しておりますし、課の中でも、そういったことが周りにあるときには。","voiceIndex":295,"id":"exchange-130"},{"speaker":"藤原委員","kind":"確認","question":"４９７ページ、介護保険特別会計で、これ、しながわ出会いの湯事業が入っているのですけれども、これはなぜ介護保険特別会計なのですか。これ、どうしてですか。健康課長、伺いますが、出会いの湯、もちろんこれ、きちんとした施策ですから、月１回ぐらいは課長自身がきちんと銭湯へ行っているのですよね、それの確認。なぜかと言ったら、すごくあそこの係、評判がいいではないですか。お伺いします。","respondent":"若生健康課長、東野福祉計画課長、川原高齢者地域支援課長","answer":"この事業は、もともとは福祉部の高齢部門のほうでモデル実施というところから、平成７年ぐらいからやっている長く歴史のある事業でございまして。人員の体制ですが、今年度は国の予算を使いまして調査等を行う予定でおりますが、来年度以降、どういった形で拡大していくかも含めて。高齢者の住宅あっせんに関するお尋ねです。窓口の職員の対応が非常によいであるとか、ご意見をいただきまして、大変ありがとうあります。","voiceIndex":298,"id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"週１回だけではなくて、隔週でいいから、週２回ぐらい行けるように。出会いの湯の日に行っているだけですから。よろしくお願いします。２４５ページ、福祉人材確保・定着事業についてお伺いします。私は、何回も要望しました。他区で直接介護従事者の方に１０万円給付している区があると。品川区でもやってほしいと何回もお願いしました。いつも検討するということですが、検討の結果を教えていただけますか。","respondent":"菅野高齢者福祉課長、若生健康課長","answer":"私からは、他区で行っている奨励金のことについての本区における検討ということでお答えします。こちらについては、私からもそちらの区に問合せをさせていただいたりとかして、事業の実態等も聞かせていただいております。出会いの湯を増やす件に関しまして、ただいまコロナ禍を経て、徐々に定員を拡大してきていまして、徐々に利用者も戻ってきているところですので、今後、浴場組合ですとか。","voiceIndex":302,"id":"exchange-132"},{"speaker":"藤原委員","kind":"質問・要望","question":"受け入れないと駄目ですかね、もう。もう諦めなくては駄目ですかね。その委員が求めているのです、どうにかしましょうと。私の質問ですけれども。効果を求めては駄目だって。公なのだから、民ではないのだ、公ですから。だけど、求めて申請する人には、ぜひ効果を今とおっしゃっていましたけれども、品川区が先駆的なのですから、それはしていっていただきたいと思います。課長、ご答弁をお願いします。","respondent":"菅野高齢者福祉課長","answer":"だからこそというところで、介護報酬というお話になっていくのだと思いますが、今、国のほうも、介護保険制度全体の構造的問題という部分で、介護報酬の見直し等で議論しているところですので、もう少しその動向を見ていきたいと思っているところです。","voiceIndex":305,"id":"exchange-133"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、国ではまだ手話を言語とする法律がなく、国連の勧告でも日本手話が公用語であるということを法律で認めることなどが求められています。ですので、ぜひ手話通訳者を毎日配置していただきたいと思いますが、いかがでしょうか。２年前に配置を１日増やしました。そのときにも拡充を求めまして、区は、利用状況を見たいということでしたけれども、どういう状況になっているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"手話通訳者の障害者支援課での配置についてです。委員おっしゃるとおり、現在、半日、週３日、配置しております。利用状況につきましては、半日たっぷり埋まるところもあれば、お客様がいらっしゃらないときもあるという状況です。","voiceIndex":308,"id":"exchange-134"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者支援課に毎日配置をしてほしいということも伺いましたので、ご答弁いただきたいと思います。","respondent":"松山障害者支援課長","answer":"手話通訳の方々は、かなり合理的配慮が進みまして、選挙ですとか、イベントですとか、様々な派遣が非常に増えている実態があります。障害者支援課に配置ができるかどうかにつきましては、また登録通訳者の方々とご相談、調整したいと考えています。","voiceIndex":310,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"事務事業概要などを見ても増えているというところなので、そうした中でやはり需要としては広がっているということだと思います。協会の方からも、聞こえる人はいつでも相談に行けるのに、聴覚障害者はできない、聞こえる人と平等にしてほしいとの声も出ています。手話通訳者を毎日配置するということは、合理的配慮の提供の１つではないかと思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"手話通訳者の配置についてです。実際問題、手話通訳者を毎日配置できるかということにつきましては、やはり通訳者の方々、２８人それぞれ派遣状況等もありますので、それらを踏まえて相談、調整し協議していきたいと考えています。","voiceIndex":312,"id":"exchange-136"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ配置を進めていただきたいと思います。区は手話通訳者の派遣をしていると思いますが、先ほど、登録者の方は２８名ということで、今、利用回数はどれだけになっているのか伺います。手話言語条例を制定したほかの自治体では、手話通訳派遣が２倍になったところもあります。さらに合理的配慮の提供を進めるために、団体利用を無料にすることが有効だと考えますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"派遣の回数ですが、今、手元にございません。それから、料金の関係です。団体派遣を無料にするですが、料金につきましては、他区の状況ですとか、あるいは、通訳者の会の方々とも実は意見交換をしながら、いつも適正な価格を決めているところです。","voiceIndex":314,"id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用回数は手元にないというお話でしたけれども、あとでお聞きしたいと思います。恐らくそこも増えていると思うのです。そもそも登録されている方が２８人ということで、やはり人が足りないという問題があると思うのです。しかし、合理的配慮の提供に向けて、さらに求められていくのだと思います。ですので、ぜひすそ野を広げて、手話通訳者の拡大を進めていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"昨年度は２５名で、３名の方が合格されて、見事２８人になったです。通訳者というのは、本当に２つの言語を同時通訳するという非常にプロのお仕事ですので、少なくとも４年、５年、しっかり学んでいただいて、２回の非常に難しい試験を合格されているです。","voiceIndex":316,"id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、２０２２年度時点では、都内でも６区１０市が実施しているということです。全国統一試験について、昨年１２月に聴覚障害者協会と通訳者の代表者の方、派遣事業をしている「逢（あえる）」、そして障害者支援課で勉強会を実施したということですけれども、その後の進捗状況を伺います。区として、手話通訳者の処遇改善を検討していただきたいと思いますが、いかがでしょうか。答弁をお願いします。","respondent":"松山障害者支援課長","answer":"通訳者を養成したいのに、半年か１年か、少し多くかかってしまうというような課題もありまして、非常に実務的なところで、今、検討を進めているです。次に、処遇改善です。","voiceIndex":318,"id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"処遇改善のほうも、今回、検診の助成を行っているということですけれども、さらに踏み込んで実施をしていっていただきたいと、これは要望しておきたいと思います。併せて検討していただきたいと思いますが、いかがでしょうか。実際、従事者であるガイドヘルパーが足りないという問題もありますので、こちらもぜひ養成研修を拡充していっていただきたいと思うのですが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"同行援護に対するお尋ねです。同行援護の課題の経済的なところには使えないという課題解決に向けて、今、検討しています。ガイドヘルパーに向けても、増やすというか、継続をしながらきちんとヘルパーとして従事していただくことを考えております。","voiceIndex":320,"id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"拡充をしていくということですので、ぜひ品川区としてさらに進めていっていただいて、利用できないということがないようにしていただきたいというふうに思います。こうしたバリアを取り除いて、障害がある方も、誰もが安心して暮らせる品川区にすることを求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-141"},{"speaker":"吉田委員","kind":"確認","question":"私からは、２３７ページの障害児者福祉施設運営費、それから２４３ページ、高齢者福祉施設運営費、両方にまたがって伺います。それから、２６７ページの区立保育園費、もし時間があれば、２５９ページのしながわネウボラネットワーク事業について伺います。もし何か見解があったら伺いたいと思います。区立園は、区として全園にそういうものがあるというふうに確認していると理解してよろしいでしょうか。","respondent":"立木保育課長","answer":"事故報告の件ですけれども、誤食ですとか、置き去りがあったりとかということで、今回、報告件数がある部分ですけれども、この原因の部分に関しましては、誤食の部分と、そのほかを含めまして、職員間の連携の部分で少しミスがあったというようなところが原因です。","voiceIndex":324,"id":"exchange-142"},{"speaker":"吉田委員","kind":"質問・要望","question":"東京都と同じように報告書様式があるというので、ぜひそちらも確認させていただきたいのですけれども、やはり私立保育園は、保育基準を満たしていたとしても配慮が必要な場合があるのではないかという区の見解が出ていて、私もそのとおりだと思って、ぜひそちらの方向で要求してほしいという意見を申しましたけれども、区立保育園についてもそうなのではないかと思うのですが、いかがでしょうか。","respondent":"立木保育課長","answer":"確かにいろいろな動きをお子さんはしますので、そこのところは職員はいろいろなところを気づかって大変だとは思うのですけれども、そこはヒヤリハットの研修ですとか、事故防止の研修もやっている中で、きちんと訓練はされておりますので、そうした中で。","voiceIndex":326,"id":"exchange-143"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺を考えていただいて、私は、さっきも言いましたけれども、保育士が１人、お医者さんに連れて行っているわけです。多分。すぐ連れて行ってくださったのだと思うのですけれども、そうすると、残りの保育士は２名ですよね。２名で、あと１９名をというのが、なかなか厳しいのではないかというふうに思いました。いかがでしょうか。一旦それでお答えをお願いします。","respondent":"立木保育課長","answer":"保育士の負担の部分に関しましては、これは様々いろいろな手法で保育に集中できるような形にできるように、様々負担軽減策に関しては、保育課も園も含めて一緒に考えておりますので、そうした中でしっかり子どもと向き合う時間を確保してまいりたいと思います。","voiceIndex":328,"id":"exchange-144"},{"speaker":"吉田委員","kind":"質問","question":"それで、先日の文教委員会では、令和４年度指定管理者による管理に対するモニタリング・評価の結果についてのご報告がありました。１回事故を起こしたから、すごくどうこうと言うつもりはないのですけれども、少なくともモニタリングの際には、事故報告も対象となるべきなのではないかと思います。こういう事故報告の扱いは、モニタリングの際にどうなっているのか伺いたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"そういった形で、公立保育園、私立保育園を含めまして、公私立連携協議会もやっておりますので、そうした中でこうした事例は共有させてもらって、再発防止に努めているところです。","voiceIndex":330,"id":"exchange-145"},{"speaker":"吉田委員","kind":"確認","question":"時間がないので、障害児者福祉施設運営費と、高齢者福祉施設運営費で伺います。そもそも指定管理者の選定の際に、建物の定期点検ができる専門性を備えていることを条件としておりましたかということと、それから、指定管理者が行った定期点検報告は、所管で報告を受けていると考えてよいでしょうか。そこに定期点検の妥当性を判断できる人が配置されているのか、その辺を確認させてください。","respondent":"松山障害者支援課長","answer":"利用者の安全性に関わるようなものについては、早急に対応させていただいているところです。併せて、適宜、施設整備課に相談をするなど、建物の適切な管理に努めているところです。各所管には、そこまでの専門家はおりませんので、施設整備課に相談しています。","voiceIndex":332,"id":"exchange-146"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。では、最終的には施設整備課のほうで、その専門性を持った点検がされるという理解でよろしいでしょうか。","respondent":"小林施設整備課長","answer":"点検自体につきましては、所管で行う場合もありますし、我々のほうで行う場合もありますけれども、当然、所管のほうで行った内容につきましても、ご相談を受けた内容を見て、これがやるべきなのか、やらざるべきなのか、そういうところは判断しています。","voiceIndex":334,"id":"exchange-147"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり区の施設ですので、最終的には、やはり施設整備課が責任を持って、所管から上がってきた報告書は点検していただきたいと思います。当然と思いますけれども、改めてお願いをして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":336,"id":"exchange-148"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、２７５ページ、保育関係事務費について伺ってまいります。今日は、保育園の調整指数、多胎児支援について伺います。先日、双子のお子様がいらっしゃるご家庭から、港区の保育園では調整指数に多胎児であれば加点されるのに、なぜ品川区には多胎児であることの加点がないのでしょうかというお問合せをいただきました。住民からの要望で多胎家庭への加点制度ができたところもあるようです。","respondent":"立木保育課長","answer":"それに対しては、今のところ、調整指数としては加点がございませんというようなその事実をお返ししているというような形で、あとは、社会情勢、他区の情勢等を見ながら、毎年見直しはかけておりますので。","voiceIndex":338,"id":"exchange-149"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私が直接お伺いしたようなご要望が区にも届いている。区民ニーズがあることも確認いたしました。想像以上に３人の赤ちゃんを育てる生活は過酷で、寝る間もなく、市の保健師の訪問を受けた際に相談したところ、ファミリーサポートセンターに一時的に預けたらどうですかと利用を勧められたそうですが、その事前面談に３人の乳児を連れていく余裕がなく、結果的に利用しなかったそうです。長い引用をしました。","respondent":"立木保育課長","answer":"今の事例に関しまして、あったかないかというところも含めて、今、手元に資料がないので、はっきりとお答えすることができません。申し訳ございません。","voiceIndex":340,"id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"少なくとも１００世帯に１軒はニーズがあります。多胎児育児を守るために、明らかに必要性があり、そしてニーズのある品川区の保育園の調整指数において、早急に、もう来年の保育園の案内がネットに出てしまっていますから、来年度はもう無理かもしれませんけれども、早急に母親が多胎妊娠中あるいは入園する子どもが多胎児であることに加点を行っていただきたいと思いますが、ご見解を伺います。","respondent":"立木保育課長","answer":"加点に関しまして、その調整指数の見直しに関しましては毎年行っておりますので、その中で、例えば多胎児だけでいいのか、それとも、例えば年子のご家庭はどうなのか、そういったことも総合的に勘案しまして、いろいろな面から検討させていただきたいと思います。","voiceIndex":342,"id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"早急に検討をお願いします。もう１点、既に保育課にはお伝えしていますけれども、大事な要望です。港区で同じマニュアルを見ると、これ、調整指数と検索すると、１３件ヒットするのです。これも前々から団体から言われているみたいですが、品川区はなぜか写真データなのです。ですから、これ、やはり子育ての品川としては、検索できるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"これは、お声をいただきまして、今、作業に入っているところでして、早急に直したいと思います。","voiceIndex":344,"id":"exchange-152"},{"speaker":"せりざわ委員","kind":"質問","question":"２４７ページの認知症検診から、見守りアイテムだったり、補聴器も含めてお伺いします。時間があれば、２４９ページの高齢者多世代交流支援施設運営費についてお伺いしたいと思います。認知症検診になりますが、令和４年度、いろいろやってみて、受診率であったりとか、受診者数も出ているかと思います。ほかのがん検診とかと比べた評価をまずお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"本来であれば９月で終わるところを１２月までご協力をいただいて、さらに延ばしていただいたというところと、昨年度、１５医療機関を倍増していただきまして、３０医療機関に引き続き受診率を上げる取組を、時期と場所は増やしましたので、あとは区の努力というところで。","voiceIndex":347,"id":"exchange-153"},{"speaker":"せりざわ委員","kind":"提案","question":"だからこそ、２０％ぐらいの陽性率が出ているのだと思うのですが、この認知症検診においては、ふらっと立ち寄って、あまり興味のない方も受けるというような環境もつくれたらいいなと思っていて、そういう意味で言うと、自分で受けようとは思わないけれども、何かしら理由があったら受けるという方をどうやってつくるかだと思うので、例えば区で言い訳をつくってあげるということも１つ方法かなと思って。","respondent":"川原高齢者地域支援課長","answer":"ただ、受診をされた年齢層は、やはり７０代の方が多かったというところでございましたので、やはり早期発見というところでは、若い層、６５歳以上の方をキャッチするような手法を考えていきたいというところと、集団検診の在り方につきましては、他区の状況も踏まえまして。","voiceIndex":349,"id":"exchange-154"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"これももっと地域におろしていただきたいと思って、今、１３ブロック、品川区で分かれていますけれども、例えば、その１３ブロックにそれぞれ希望大使がいて、すぐ会えるような環境というか、自分の知り合いが希望大使なのだという、それだけで認知症になっても怖くないのではないかと思える正に希望になると思うので、そこら辺もぜひご見解をお聞かせいただければと思います。","respondent":"川原高齢者地域支援課長","answer":"実は作成している「品川“くるみ”認知症ガイド」という冊子に、本人大使の方のイラストを入れるような形で、今、検討しています。そして３点目、スマホ教室のところでは、児童センターとの連携も含めて実施をしてまいりたいと考えています。","voiceIndex":351,"id":"exchange-155"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":126026,"voices":353}},{"id":"r05-20231006-4","meetingId":"r05-c-settlement","date":"2023年10月6日","dateIso":"2023-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"おはようあります。私からは、２９３ページ、健康づくり支援事業費、２９５ページ、ＡＥＤ管理費、３１１ページ、カラス及び外来種対策事業についてお伺いします。１０月６日、今日は世界初トーキー映画の日です。していない。令和５年３月の予算特別委員会でも質問させていただきましたが、アプリが新しくなりましたので、区民の方の利用者数と、前回と今回の比較を踏まえて、実績や評判もお知らせください。","respondent":"若生健康課長","answer":"今回８月からアプリを開始していますけれども、新しいほうの利用状況、参加者数につきましては、１０月２日時点で３,０７６名の方にご登録いただいておりまして、まずまず順調な滑り出しかなと考えています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"私も新しい機能の中で写真を投稿させてもらっていて、採用されると、とてもうれしく思っております。先日、１０月３日、川崎市では、歩いてためたポイントを小学校に寄附し、応援特典を参加企業から得られるアプリを使った健康事業、「かわさきＴＥＫＴＥＫ」を始めました。他の所管と連携した効果的な取組と考えますが、今後、アプリはどのように進んでいきますでしょうか。区のお考えをお聞かせください。","respondent":"若生健康課長","answer":"社会貢献とか、景品というか、ポイントをどのように還元できるかというところにつきましても、いろいろと今後、広がりのある仕組みというか、事業ですので、そういった展開についても、他自治体の事例も参考にしながら検討してまいりたいと思います。","voiceIndex":6,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"今後も幅広い世代で健康づくりの動機づけが高まるように、楽しく面白い仕掛けに取り組んでいただけるようお願いいたします。続きまして、ＡＥＤ管理費についてお伺いします。品川区ではＡＥＤの設置を進められておりますが、現状の設置台数、設置場所、また今後の取組についてお知らせください。","respondent":"若生健康課長","answer":"設置場所としましては、区が設置している公共的な施設、それから学校、文化施設等も含めたところで２９０台となっています。今後、どういったところに設置できるかというところは、内部で様々検討しています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"えのした委員","kind":"質問・要望","question":"例えば、区民まつりでのブース設置、スポーツ中やその直後は心臓突然死のリスクが、スポーツをしていないときの１７倍に高まると言われているので、各スポーツ連盟、団体、指導者、保護者の方への普及活動、また、先ほどの健康ポイントアプリと連携した取組などはいかがでしょうか。場所に行くだけではなく、講習会に参加された場合にはスペシャルポイント贈呈などはいかがでしょうか。","respondent":"若生健康課長","answer":"今後、区民の方に、使い方も含めまして、ＡＥＤを認識していただいて、即時に対応できるような周知に、より分かりやすく努めていきたいと思います。","voiceIndex":10,"id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"ハトのふん害についてもお伺いしますが、以前のご答弁で、区民からの相談に応じて注意、看板の設置、パトロールなどを実施して対応していると伺っておりますが、その後、区としてどのような取組をしているのかお知らせください。","respondent":"河内環境課長","answer":"ハトの対応ですが、業者のほうで対応することに変わりはございませんが、実績、それから方法、価格などを勘案いたしまして、しっかりと実績が上がるようなものを進めるとともに、補助金などにつきましても、他の自治体の動向などを踏まえて検討を進めているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私からは、２点お伺いいたします。３０７ページの猫の不妊・去勢手術費助成、３０１ページの不妊治療助成事業について、それぞれお伺いしてまいります。初めに、猫の不妊・去勢手術費助成から質問いたします。私の地域に猫のボランティアで熱心な方がいまして、よく話を伺います。","respondent":"舩木生活衛生課長","answer":"前年度ですと、１９の地区を指定していたわけですけれども、また今年度も、地域の猫の問題に困られているという方々から、新たにこういった取組を考えてみたいというお声を二、三件ほどいただいておりますので、そういったお問合せがあった場合には。","voiceIndex":15,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"一般枠での不妊・去勢手術の数と、共生モデル地区での不妊・去勢手術の数を見ると、着実に地域猫の数も減っているということを確認させていただきました。そういった意味で、例えば５人いれば、共生モデル地区とまではいかなくても、共生モデル地区の前段階のサブ共生モデル地区のような形として、不妊・去勢手術を一般枠よりもさらに助成が利いたりしていくようにするのはいかがでしょうか。","respondent":"舩木生活衛生課長","answer":"いずれにしましても、モデル地区は長年の実績を積み重ねてまいりましたが、こういった地域の実情を考慮した活動の仕組みを整備いたしまして、それと同時に、そういった地域猫の活動を区として。","voiceIndex":17,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"そのコミュニティの中でも、約１０万円の不妊・去勢手術費を出し合ってなされていたということでした。こういった対策についても、引き続き検討していただければと思います。続きまして、３０１ページの不妊治療助成事業について質問いたします。ぜひ品川区独自で、特定不妊治療の先進医療に対するさらなる助成金制度を求めますが、品川区のご所見をお伺いしたいと思います。","respondent":"若生健康課長","answer":"区としては、東京都の先進医療の助成制度はご案内のとおり、１５万円上限で、かかった費用の１０分の７を助成するということで、かなり手厚い制度になっていて、他区でも上乗せとか、あるいは自由診療に対する助成まで広げている区もあるということは認識しているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"意見","question":"確かに、東京都から保険適用外で先進医療を行った際には、１０分の７という手厚い支給がありますけれども、特定不妊治療をした際に、先進医療をしたらどうかとなったとき、その後に、これが駄目だとなって自由診療をやってみようとなったときには、混合診療になれば全て実費の支払いともなります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"本日もよろしくお願いいたします。私からは、３２９ページのプレミアム付区内共通商品券発行助成、２９３ページの健康ポイント事業運営委託、３２５ページの中小企業事業資金融資あっせんについて伺います。３２９ページのプレミアム付区内共通商品券発行助成について伺います。区商連からの要望、様々なメリットがあることを踏まえ、当会派でも品川区に同じ要望をしております。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問は、いわゆるデジタル商品券についてのご質問と認識しております。デジタル商品券は、ただいまご指摘のようなメリットがある一方で、利用者あるいは店舗側の課題もあるということで認識しています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"どうなるか分からないですが、振込手数料に関する減免交渉の余地はあるのではないかと考えております。他区では、例えば３年程度、紙と併用して段階的に試行している事例や過去の実績があります。段階的に併用している試行期間の間に、昨日お話ししたはじめてのスマホ体験教室やスマホよろず相談でやり方を教えて、紙からデジタルの商品券にシフトしてもらうのがよいと考えます。","respondent":"小林商業・ものづくり課長","answer":"先行事例の中でも、実際にそういった声も出ておりますし、新聞報道などでもそういう課題があるところです。こういう課題をどうクリアにしてやっていくかということも含めまして、引き続き検討なり協議を続けてまいりたいと思います。","voiceIndex":25,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ前向きに検討をお願いします。これは私として、とても重要だと考えています。９月１９日の日経新聞夕刊の記事では、紙が復活したり、ネガティブな意見も掲載されていました。チャットＧＰＴをデジタルと置き換えてもいいのではないでしょうか。これらの実現を要望し、このテーマを終わります。続いて、先ほど他の議員が質問されておりましたが、２９３ページの健康ポイント事業運営委託について伺います。","respondent":"若生健康課長","answer":"健康ポイント事業で昨年度実施後のアンケートに関して、不満というか、満足できなかった点ということでのお声ですが、１点目は、景品が抽選で、応募者が多くて、なるべく幅広く裾野を広げたいというところではあったのですけれども、ポイントが上位に当たる。","voiceIndex":27,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどのデジタル地域通貨の導入により、大幅にこれがやりやすくなり、利用者の要望に応えやすくなると考えます。今後の検討を要望いたします。次に、３２５ページの中小企業事業資金融資あっせんに関連して伺います。主に年間売上げ１,０００万円以下、大企業と取引している個人事業者が影響を受けます。そこで、現在実施している緊急資金支援制度を利用することができるのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"現在、区では緊急資金としまして、物価高騰等総合支援資金というものを設けております。これについては、事業計画を出していただきまして、設備資金、運転資金というものに対して苦しい事業者の方に対して、利用が可能な制度となっているところです。","voiceIndex":29,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"ですので、この利用条件を、増税分が考慮される税引き後利益５％減も対象にするか、もしくは消費税支払い分を融資対象にするなど、条件が満たしやすくなる変更を要望いたします。それから、今後、制度利用の増加の可能性がありますので、来年度予算での予算総額の上乗せ、それから、受付期間のさらなる延長を併せて要望いたします。品川区としての考えをお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"こういったいろいろな制度、相談制度も含めまして、ご支援・ご案内をする中で、対応を進めてまいりたいと考えております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"多くの困る事業者の方々に知っていただくことがとても大事だと思いますので、ご案内いただきたいと考えています。そのところも地元の事業者の方にとっては必要なピースだと思いますので、ぜひとも前向きに今後ご検討いただきたいと要望させていただきまして、質疑を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"２９５ページ、休日診療委託、３０３ページ、予防接種費、３０１ページ、健康診査費、時間があれば２９５ページ、公衆浴場について伺います。伺いますけれども、この間、この事業にコロナ対策として加算がされていると思いますが、その内容について伺います。その加算を除いたそもそもの委託費は幾らでしょうか。そして、その金額というのはいつから変わっていないのでしょうか。以上３点伺います。","respondent":"若生健康課長","answer":"休日診療に関してのお問合せです。休日診療について、令和３年度から診療に際して、感染予防等の医師会の診療所の負担というところを考慮しまして、固定の診療所については１日５万円、そのほか輪番制については１日２万円ということで、助成を上乗せしています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は８年前の決算特別委員会で、２０１５年１０月７日なのですけれども、伺ったのですが、このときに課長が、「平成１３年ぐらいから大きく変わっていない」と。その状況の中で、今、両医師会からは悲鳴が上がっています。伺いたいのですが、先ほど加算の話がありました。少なくともこれは継続すべきではないでしょうか、伺います。ですから、上げるべきではないでしょうか、伺いたいと思います。","respondent":"若生健康課長","answer":"そう考えますと、必ずしも診療が減ったことが問題かというところは、いろいろと考える必要があると認識しています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそもこの事業を始めた当時に比べれば、この事業というのは区民の欠かせない事業になっているわけですから、患者数は、そのときに比べれば相当増えているのです。私は伺ったのですが、少なくとも、今のコロナの加算をやめる状況ではないと思うのですけれども、少なくともこれは継続すべきではないか。医師会の皆さんも、そういう強い思いがあるわけですが、もう一回伺いたいと思います。","respondent":"若生健康課長","answer":"コロナの加算についてですけれども、これは今年度も継続はしております。今後ですけれども、現在、コロナも５類になりまして、医師会の側の診療所についても、厳しいコロナの利用制限というところは、大分緩和してきているということも聞いております。","voiceIndex":39,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"十分確認した上で、しっかりと私は継続していただきたいと思います。よろしくお願いします。今年の品川区議会の中でも、男性接種への助成を求める質疑もなされています。医師会からも区議会各会派に対して、ＨＰＶワクチンの男性接種への助成の要望も出されています。現場の声が、議会や行政を動かしてきていると思うのです。既に中野区などは始めていると伺っていますが、お考えを伺います。","respondent":"坂野保健予防課長","answer":"それに対して、東京都知事が検討すると報道等では出て、議事録等を見ますと、「諸外国や国内の動向、国の検討状況を総合的に勘案しまして、ＨＰＶワクチンの男性接種に係る区市町村への支援について検討してまいります」という答弁がされているです。","voiceIndex":41,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ぜひ素早い対応というのをお願いしたいと思いますし、品川区として、ぜひやっていただきたいと思います。次に、これも医師会から要望を出されているのですが、就学前の幼児に対する三種混合ワクチンです。分かればでいいのですけれども、就学前の追加接種をやっているお子さんというのはどれぐらいいらっしゃるのか、分かれば伺いたいと思います。","respondent":"坂野保健予防課長","answer":"ＤＰＴの追加接種ということですが、申し訳ございません、区として何人、どれぐらいやっているかという数字の把握は、持っていない状況です。","voiceIndex":43,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほとんどおられないと思うのです。ですから私は、小児に対する感染症リスクを少しでも減らすために、就学前の三種混合ワクチン接種への助成というのも実施していただきたいと思いますが、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"今、三種混合ワクチンについては、ワクチンそのものの変更とか、接種時期の追加あるいは変更等も含めて、総合的に国のほうで検討しておりますので、区としてはその動向を注視してまいりたいと考えております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ注視だけではなくて、検討して実施していただきたいと思います。１点だけ。特定健康診査で区独自に超音波検査を導入していただきたいと、区民や関係者から要望が上がっているのですが、超音波検査の有効性についてと、ぜひやってもらいたいのですが、やっていない理由というのをお伺いします。","respondent":"坂野保健予防課長","answer":"特定健診での超音波検査ということですけれども、具体的にどの部位が対象なのかが分からないものですから、何ともお答えし難いところです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"確認したいのですが、まずその内容、品川健康センターでやっているプログラム、またインストラクターは、エスフォルタ直営店と質が同じなのか、クオリティ的に同じなのか、それとも健康センター用に、少し質とか、トレーナーのレベルをある程度落としてやられているのか、その点はいかがでしょうか。","respondent":"若生健康課長","answer":"一方、区の健康センターにつきましては、公営ですので、幅広い年代の方が利用できるように、フリー利用のマシン利用とか、スタジオでのコース型の教室とか、希望すればパーソナルレッスンというのもやっておりますが、インストラクターの質がどうかというところにつきましては。","voiceIndex":50,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。私もかつて利用したことがあるのですけれども、一方で、民業圧迫にならないのかなという懸念もありまして、その点はいかがお考えなのかということと、そして何より肝腎なのが、健康センター事業で区民の健康増進の効果というのは出ているのでしょうか、伺います。","respondent":"若生健康課長","answer":"健康増進の効果というところにつきましては、数値的になかなか表すのが難しいのですが、モニタリング評価を毎年やっていたり、満足度調査の結果を見ましても、満足度というのは８割を超えている状況でございまして、日々健康増進に効果があったという声もありますので。","voiceIndex":52,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"今、モニタリングのお話が出ましたけれども、令和４年度の総括シートによりますと、令和２年度・令和３年度は収支で赤字が出ております。これはコロナが原因かなと思っているのですけれども、令和４年度は収支がぴったり０円になっているのですが、これはどういった理由なのでしょうか。","respondent":"若生健康課長","answer":"休業ですとか、利用定員制限というのも行っていましたので、当然その分、利用者の収入は減るというところになってございまして、これがコロナ禍という理由でしたので、区といたしましては、指定管理事業者にそこを全て経営努力でというところは難しいということで。","voiceIndex":54,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。それで、先ほども申しましたとおり、区民料金が品川健康センターは５００円、荏原健康センターは４００円になっているのですけれども、この料金は、区民の方と区外の方が同じという状況だと思います。ですが、指定管理料は品川区民の皆様の税金が使われているので、そろそろ区民の料金と区外の方の料金に差をつけるべきかなと考えておりますけれども、その点はいかがお考えでしょうか。","respondent":"若生健康課長","answer":"フリーの利用については、区税の公平性の観点というのもありますけれども、受付事務等もなかなか、区民か区民以外で判別するところに、受付事務が煩雑になるとか、いろいろそういったところもございまして、現状では料金に差を設けるのは難しいというところで認識しております。","voiceIndex":56,"id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"区民か区外かは、住所確認とかをすればいいだけかなと思っていますので、その内訳というのもあるかと思いますけれども、そろそろ区民の方が５００円だったら、区外の人は８００円とか１,０００円ぐらいいただいてもいいのかなと考えていますけれども、その点、よろしくお願い申し上げます。続いて、新型コロナウイルスワクチン接種に関して、コロナ後遺症、またワクチン後遺症についてお伺いいたします。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"区におきましても、いわゆる遷延する症状におきまして、具体的な相談等は受けていないところです。ただ、健康被害救済制度の受付窓口ですので、そうしたところはしっかりと区民の方に説明して、受付をしていきたいと考えています。","voiceIndex":58,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ただ、新しいウイルスであり、新しいワクチンであり、仕方がないのですけれども、時がたつにつれ、そうした事実が解明されることになってくるかと思うのですが、こうした現状に対する区のご見解と、区はそうした情報をいろいろ注視し、任意接種ということに留意しつつ、区民に対し適宜適切な情報提供をしていっていただきたいと考えていますけれども、お考えはいかがでしょうか。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"ワクチンの安全性についてのご質問かと考えています。ワクチンの安全性につきましては、国の審議会で検討いただいておりまして、その中で、現在重大な懸念は認められないという評価をされていると受けているところです。","voiceIndex":60,"id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"３０１ページ、出産応援事業、２９５ページのかかりつけ医療定着推進事業について質問します。引上げになった出産一時金の５０万円と合わせて、出産に対して６５万円の補助が今あるということだと思います。そうなると、実際の出産にかかる費用に近くなってきているとは思うのですが、今回、ギフト給付についてお伺いしたいと思います。区としてのお考えを伺います。","respondent":"若生健康課長","answer":"区といたしましては、当初の国や都の説明によって、この事業自体が、出産される方とか子育てをされる方への支援を主眼としておりまして、そういった意味で、子育て等に利用可能なものというところで給付も考えていたという考え方がございまして、国の説明では。","voiceIndex":63,"id":"exchange-029"},{"speaker":"せらく委員","kind":"質問・要望","question":"当区も区民の声を聴いていくというお考えがあると思うのですけれども、今年度の妊娠８カ月頃アンケートの結果を踏まえて検討いただきたいと思いますが、今年度のアンケート内容についても併せてお伺いいたします。","respondent":"若生健康課長","answer":"繰り返しになってはしまうのですが、東京都のクーポンと同時に合わせて行っているという関係から、それをまた切り分けて現金化するというところになると、システム的な対応などがいろいろ煩雑になってきて、その分コストもかかってくるという事情もございまして。","voiceIndex":65,"id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。物価高騰の中、持ち出し額が多いということもあり、家計に充てることは十分子育てにつながると考えておりますので、こちらは利用者の声もしっかり聴いていただきたいと要望いたします。続いて、かかりつけ医療定着推進事業について質問いたします。かかりつけ医紹介窓口の利用ターゲットは、全区民になるでしょうか。加えて、実際の利用者の年齢層や属性をお知らせください。","respondent":"若生健康課長","answer":"かかりつけ医療定着推進事業についてですが、ターゲットは区民全体ということになってございまして、特に限定してございません。それから、利用者の年齢層等の属性については確認していないところなので、区としても把握していないところです。","voiceIndex":69,"id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"健康を維持するためにも若い世代からにも利用してほしいと思っています。今、かかりつけ医紹介窓口は電話もしくはファックスで、平日の９時から１７時という時間です。かかりつけ医紹介窓口から病院を紹介した際の引継ぎ体制などはありますでしょうか。この２点について見解を伺います。","respondent":"若生健康課長","answer":"ＡＩチャットボットですとか、若い方ですとか、スマホとかをご利用したりというところでの仕組みというところは、医師会との協議、調整が必要になってくるところではありますが、そもそもこのかかりつけ医の仕組みが、身近に自分がかかりつけ医を持っていない方向けに。","voiceIndex":71,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私からは、２９９ページ、母子保健指導事業費、３０３ページ、予防接種費、３２１ページ、産業連携推進事業費、３２３ページ、創業支援施設等経費についてお伺いいたします。１点目に、予防接種費についてお伺いいたします。２点目に、母子保健指導事業費についてもお伺いいたします。３点目にも行きます。産業連携推進事業、創業支援施設等経費についてお伺いいたします。","respondent":"坂野保健予防課長、若生健康課長、石橋品川保健センター所長、小林商業・ものづくり課長","answer":"今年の８月末時点ですが、ユニークユーザー数が、これは一つのアカウントで子どもを複数登録できるものですから、２,４６４のアカウントで。今後、母子保健等は自治体のシステムの標準化の対象になっておりますので、今後システム改定に合わせて。検討というお話ですが、現在も月齢やタイミングに応じてサポートを実施しておりますので、まずは既存の事業をしっかり周知し。ＳＨＩＰの特徴としましては、近くにあります五反田バレーとの連携という活動の中で、アクセラレーションプログラムという。","voiceIndex":74,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"島根県と番組とのコラボ特設サイトや、監督やキャストとの聖地巡りツアーなどのシティプロモーションや、観光客誘致の取組にも注目しておりますが、今日は産業経済費ですから、行政評価シートの１０３ページのモンゴル高専についてお伺いいたします。５月と８月に実施した人事交流の概要と、交流を通して得られた気づきについてご説明ください。今後の展望について、区のご見解をお聞かせください。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長","answer":"ただいまモンゴル高専の事業についてのお尋ねがございました。品川区では、具体的に言いますと、平成２９年、２０１７年から、区内中小企業の海外からの技術人材の確保ということも目的としまして、人事交流を続けてきたところです。品川区で母子保健事業として実施しております育児学級ですとか、そういうところも含めて、一人で悩まないでくださいということは今後も周知をしていきますし。","voiceIndex":79,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"ぜひ産前産後ケアを含めて、総合的にお母さんたちが自分の体を休められるように、よろしくお願いいたしたいと思います。交流の件、ありがとうございました。長期的なアウトカムに向けて、例えば、五反田バレーとモンゴルとの実際の取引につなげていくためのステップを踏んでいくようなイメージを持っておりますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"今後の実績指標ですけれども、現在、ご指摘のありました行政評価シートの中では、一つ、区内中小企業の関心としましては就職が高いので、それプラス交流ということも今後拡大していけるように、いろいろ進めてまいりたいと考えております。","voiceIndex":82,"id":"exchange-035"},{"speaker":"澤田委員","kind":"質問","question":"本日もよろしくお願いいたします。３２７ページ、品川区運送事業者等燃料費高騰対策支援金、３０３ページ、各種がん検診についてお伺いします。は３２７ページ、品川区運送事業者等燃料費高騰対策支援金です。対象事業の分野は運輸・水産とありますが、この事業の具体的な支援対象と支援実績についてお示しください。","respondent":"小林商業・ものづくり課長","answer":"具体的な対象事業ですけれども、タクシー事業者ですとか、トラック事業者、あるいは軽貨物自動車運送事業、あとは屋形船の事業者など、こういうところがあります。トータルの支援実績としましては、３０８件です。","voiceIndex":86,"id":"exchange-036"},{"speaker":"澤田委員","kind":"確認","question":"支援対象、支援実績ともに確認いたしました。当初予算額は２億３,１１２万円となっておりますが、実績の決算額は５,１３４万４０４円であり、執行率は２２.２％となっております。この支援金は３０８件に支給されたとのことですけれども、当初の見込額よりも、なぜ低かったのかとお思いでしょうか、そのお考え、理由について、区としての見解をお聞かせください。併せて、周知の方法をお知らせください。","respondent":"小林商業・ものづくり課長","answer":"実際この予算、昨年度、令和４年度の補正予算で実施した事業でございまして、補正予算の成立時期ということもございまして、２月１３日から３月１７日という期間の中で実施したものです。可能な限り、この中でも年度末に間に合うようにということで実施したところです。","voiceIndex":88,"id":"exchange-037"},{"speaker":"澤田委員","kind":"質問・要望","question":"国による燃料油価格激変緩和措置の期間が令和５年１２月末までとされている中、平時の物流や発災時の協力事業者として協定を結んでいる運送事業者、品川区の観光を盛り上げる舟運事業など、様々な区内の事業者の方々が廃業してしまうことのないように、令和５年度も引き続き、支援策を継続して行っていただきたいと要望いたしますが、区としての見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"こういった国とか都の経済支援という対応も含めて状況を見ながら、経済動向として、何を区として必要な支援を行うべきかということを、引き続き考えてまいりたいと思います。","voiceIndex":90,"id":"exchange-038"},{"speaker":"澤田委員","kind":"質問・要望","question":"国や都の経済支援の動向を見ていかれるとのことですが、ぜひ、困っている事業者の方たちのために何ができるかということを、区としても考えていただくことを要望いたします。続きまして、３０３ページ、各種がん検診についてお伺いします。品川区では、様々ながん検診を無料または一部負担金を徴収する形で行い、区民の皆さんの健康と命を守ろうと努めておられます。","respondent":"若生健康課長","answer":"それで、取組としましては、さらに肺がん・乳がん・子宮がん検診については、未受診者に対して現在、再勧奨通知というのを、また個別におはがきをお送りしたりということをやっておりまして、乳がん・子宮がんにつきましては。","voiceIndex":92,"id":"exchange-039"},{"speaker":"澤田委員","kind":"質問","question":"乳がん・子宮がん・肺がん検診での未受診者に対する個別通知、再通知など、様々な取組を行われていることが分かりました。そこで、乳がんですけれども、１０月１日はピンクリボンデーとして、区内の１３橋梁がピンク色にライトアップされ、乳がんの周知啓発のシンボルとして、まちを華やかに彩っていますけれども、こちらはＳＮＳなどでは発信されたのでしょうか。","respondent":"若生健康課長","answer":"１０月１日のピンクリボンデーのライトアップは、河川下水道課のライトアップのところとタイアップしてやらせていただいておりまして、ＳＮＳの発信というのはやっておりませんでしたので、今後検討してまいりたいと考えています。","voiceIndex":94,"id":"exchange-040"},{"speaker":"澤田委員","kind":"質問・要望","question":"まだＳＮＳでの発信はされていないということでしたので、ぜひきれいな夜景などとともにＳＮＳで発信して、アピアランスケアなども一緒に周知していただけるとありがたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、３０３ページ、予防接種委託、高齢者インフルエンザのワクチン接種について、子宮頸がんのワクチン、時間がありましたら、３０７ページの犬の登録・予防注射についてお伺いします。最初に、３０３ページの予防接種委託、高齢者インフルエンザのワクチン接種についてお伺いいたします。医療的な部分でお伺いしますが、今年の流行の特徴をお知らせいただきたいと思います。","respondent":"坂野保健予防課長","answer":"ワクチンの効果です。インフルエンザのワクチンですと、流行を抑えるというよりも、どちらかというと重症化予防に効果があるとされておりまして、感染を抑える効果というよりも、重症化を抑えて、例えば入院などの件数を減らしていくという効果があるものかなと考えています。","voiceIndex":98,"id":"exchange-042"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域の方から、この流行を得て、早く接種をしたいというお声が結構ありましたが、実は病院の予約をすると、１０月以降しかできないと。それと、我が会派の若林委員からも、歳入の審査の際に確認させていただきました。都議会出身の区長、そしてまた、東京都から来られた副区長と、東京都との連携というのはばっちりであると考えていますので、その辺を強力に進めていただきたいと思いますが、見解を伺います。","respondent":"坂野保健予防課長","answer":"ワクチン接種の時期を今年のような流行のときは前倒しできないかということですが、今使われている不活化ワクチンは、技術的な話をしますと、鶏の卵を使う関係があるので、この時期を変更するのは、技術的には相当難しいというのがあります。","voiceIndex":102,"id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"子宮頸がんワクチンについてお伺いいたします。検診を受けられている方、子宮頸がん検診の受診率は、品川区が設定している目標よりも高い結果が出ていると確認していますが、予防と検診が発症を抑えていく重要な鍵となっていると思います。キャッチアップを含めて、さらなる勧奨を要望いたしますが、見解を伺います。","respondent":"坂野保健予防課長","answer":"時期は未定ですが、来年の夏前後をめどに考えているところです。","voiceIndex":104,"id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"先ほどもありました男性へのＨＰＶワクチンの接種につきまして、都議会で前向きな答弁が出たと。私は前向きな答弁であったと受け止めました。そういう効果があると私は捉えているのですけれども、品川区として、先ほども申し上げたとおりですが、東京都と連携していただきながら、よく情報を得て、早めに品川区として進めていただきたいと思いますが、改めて見解を伺います。","respondent":"坂野保健予防課長","answer":"ＨＰＶワクチンの男性への補助です。既にご承知のように、中野区で始まっているものですけれども、先日の都議会での小池知事の答弁にもありましたとおり、もし東京都から何らかのスキームが出た場合には、区としても考えていきたいと思いますので、よろしくお願いします。","voiceIndex":106,"id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都のスキームが出たらということですが、品川区はやりたいのだという姿勢をしっかり示した上で、スキームを待っていただきたい。その方向で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-046"},{"speaker":"おぎの委員","kind":"質問","question":"本日は３０３ページ、新型コロナウイルスワクチン接種についてお伺いします。今回の新型コロナ感染症が始まって３年半が過ぎました。厚生労働省のデータでも、乳幼児から若い世代の重症化率はほぼ０％となっており、社会は落ち着きを取り戻しつつあります。品川区でも予防接種健康被害救済制度の申請の窓口を行っているようですが、品川区では、申請は現在何件でしょうか。進達状況を教えてください。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"区としましては、こちらの制度としまして、区が窓口となりまして、書類に不備がないかを確認しましたら、東京都、また国に進達するという制度になっております。区の８月末現在の受理件数ですが、３６件受理しておりまして、そのうちの２９件を東京都・国に進達しています。","voiceIndex":110,"id":"exchange-047"},{"speaker":"おぎの委員","kind":"質問・要望","question":"この品川区でも、人知れずワクチンの後遺症に苦しんでいる方がいるということを、私たちは知るべきだと思います。ワクチン接種を個人の判断に委ねる以上、メリットとデメリット双方をきちんと周知することが重要と考えますが、品川区はホームページにおいて、デメリットの部分も周知に努めていると言えるでしょうか。これで区民にきちんと周知をしているとは言い難いと思われますが、どうでしょうか。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"給付が決定しましたら、その給付手続につきましても、責任を持って速やかに進めていきたいと考えています。副反応は予防接種後に起きますので、そうした場合は、東京都の副反応のコールセンターがございまして、２４時間受け付けております。","voiceIndex":112,"id":"exchange-048"},{"speaker":"ひがし委員","kind":"質問","question":"本日もよろしくお願いいたします。最初に、母子保健費の産後ケア事業、特に日帰り型についてお伺いいたします。ホテルでの産後ケアの利用については、とても評判がよかったと伺っておりますが、今回移転に当たり工夫した点、そして現時点での、分かる範囲で大丈夫なのですが、保健センターでの産後ケアの利用状況、また課題があれば、併せて教えてください。","respondent":"石橋品川保健センター所長","answer":"ホテルでの実施を検討しなかったのかというところになりますけれども、ホテルでの実施が大変好評だったことは、こちらも認識しております。ホテルの継続を検討しなかったのかということになりますが、区が産後ケア事業の開始後、産後ケア事業の国のガイドラインが発出されました。","voiceIndex":115,"id":"exchange-049"},{"speaker":"ひがし委員","kind":"質問","question":"産後ケアは、産後４か月未満の母親が、体と子育ての不安に対して助産師に相談でき、産後の不安を解消する場だと認識しておりますが、産後の体の負担、そして子育ての中で、このような電話、また書類の作成などは負担になるのではないでしょうか。そうすることで、利用者の負担軽減になると思いますので、ぜひ前向きに検討していただければと思うのですが、いかがでしょうか。区のお考えをお聞かせください。","respondent":"石橋品川保健センター所長","answer":"現在、区役所のあらゆる申請の電子化が進んでいることをはじめ、本事業においても今後、利用者の利便性、利用者の年齢層なども検証し、より利用しやすい申請方法、空き状況の確認方法を検討してまいります。","voiceIndex":117,"id":"exchange-050"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、デジタルネイティブが増えていくことも見据えて、子育て世代、若い世代が利用しやすい事業になるように、予約のデジタル化、また、仕組みのブラッシュアップについても検討していただきたいと要望します。障害がある方にとって、がん検診のお知らせが送られてきても、自分たちの疾患に病院が対応してもらえるのか分からず、受診から遠のいているとのお話を伺いました。","respondent":"若生健康課長","answer":"そういったところを課題として認識しているところではありますが、そういった対応というところにつきましては、ご相談を受けた際には、そこでどういった困難があるのか、どういった支障があるのかというところは、医療機関で丁寧に聞き取っていただく必要があると思いますので。","voiceIndex":119,"id":"exchange-051"},{"speaker":"ひがし委員","kind":"質問","question":"例えば、現在送られている検診用紙の病院の一覧に何か一言記載するなど、配慮があればと思うのですが、いかがでしょうか。難しい状況もあるとは思いますが、現状困っている方がいるということも変わりがありません。実際に先ほどお話があったように、障害を持った方々が困っているということ、さらに検診につながるような支援を引き続きお願いしたいと思います。答えられる範囲でご見解をお願いします。","respondent":"若生健康課長","answer":"お知らせを検診の実施機関の一覧に表示してはというご提案でしたが、例えば車椅子対応可とか書いても、実際通れるかどうかとか、幅とか、いろいろその方の状況によっても異なるので、なかなか一律には難しいですけれども、今後、医師会等と意見交換してまいりたいと考えています。","voiceIndex":121,"id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"２９５ページのＡＥＤ管理費と、あと３０５ページ、自殺予防対策事業と、横断して３２３ページの中小企業活性化事業費、時間があれば３０５ページの新型コロナウイルス感染症対策をお聞きします。先ほど、えのした委員もされました。９月の本会議において、コンビニへの設置の検討を進めていくというようなお話がありましたが、それ以外の場所においての設置の検討はありますでしょうか。お願いします。","respondent":"若生健康課長","answer":"ＡＥＤの設置拡大につきましては、様々検討を進めているところでございまして、まずはコンビニへの設置に向けて、今検討を進めているところで、その設置を進めていった先に、またほかのところについては検討してまいりたいと考えています。","voiceIndex":129,"id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そこでぜひお願いしたいことが、介護施設への設置です。というのはなぜかというと、やはりＡＥＤは値段が高い。大田区においては設置補助事業も始まっておりまして、初期費用ですと３２万円余まで、設置の補助事業というか、給付が下りるというような事業も始まっておりますので、ぜひ他区の事例も参考にしていただいて、やはり命を守るというところで検討していただければと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"それから設置補助、大田区のほうで進めている件につきましては、区としても認識していますけれども、まずは確実にコンビニへの設置というところについて進めて、その後助成等も視野に入れて考えてまいりたいと思います。","voiceIndex":131,"id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"横断的なことだと思うのですけれども、ぜひ早急に、前向きに進めていただきたいと思います。次に、中小事業活性化事業ですけれども、先ほど山本委員等の質疑であった支援策といいますか、あっ旋事業というのは、物価高騰等総合支援資金というような名目のあっ旋事業でよろしいでしょうか。","respondent":"小林商業・ものづくり課長","answer":"そのとおりで結構です。","voiceIndex":133,"id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私が聞き逃していたら申し訳ないのですが、結果的におっしゃられた税引後利益にしてほしいというような要望に対しては、お答えはいかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"物価高騰等総合支援資金につきましては、やはり目的として、物価高騰というところを対象に要件としております。","voiceIndex":135,"id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えばインボイスの導入でお困りの方において使えるあっ旋事業というのは、制度的にどういったものがありますでしょうか。","respondent":"小林商業・ものづくり課長","answer":"物価高騰、例えばですけれども、単独の理由ではなくて、物価高騰も含めて、例えばそういったインボイス対応も含めてということで、設備投資なり、あるいは運転資金ということでございましたら活用の可能性はありますし。","voiceIndex":137,"id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"結局それだと、やはり売上げ１,０００万円以下の小規模事業者にとって、何の解決にもならないと思うのです。例えば漫画家、声優、アニメーターのような方などは、クールジャパン、日本の文化、皆さん子どもの頃から慣れ親しんでいる漫画・アニメの作り手の方の５人に１人が、インボイスが始まると生活が立ち行かなくなって、廃業しなくてはいけないというようなことをおっしゃっています。","respondent":"小林商業・ものづくり課長","answer":"こういった中での活用や、あるいはインボイスに関わるところでいきますと、国の支援制度があります。このようなものを適切にご案内しながら、支援を進めてまいりたいと思います。","voiceIndex":141,"id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひその辺しっかり、もう少し考えていただきたいと思います。倒産も増えております。ぜひそういったところを真剣に考えていただきたい。最後に、先ほどコロナ感染対策についておぎの委員がお話しされたところで、時間がないので要望だけですけれども、やはり品川区のホームページを見ても、内容が薄いなと感じます。国の事業とはいえ、そこは区でしっかりできる限りのことをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-059"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３０３ページ、保健予防費から小児インフルエンザワクチンについて、２９９ページ、母子保健指導事業費に関連しまして、病気の子どものケア教室開催について、時間がありましたら、３０１ページ、成人歯科健診についてお尋ねしてまいります。そこでお聞きしますが、その前の６か月から１歳までの間の乳児のワクチン接種費の補助が今年度も見送られた、この理由について区のお考えをご説明ください。","respondent":"坂野保健予防課長","answer":"実際問題、幾つかの区が少しずつ拡大をしていまして、現状６か月から打てる区が、２３区のうち８区です。今年度は従来どおりで始めさせていただいたのですが、大事な課題だと私も認識しておりますので、今後年齢の拡大については検討していきたいと考えております。","voiceIndex":145,"id":"exchange-060"},{"speaker":"こしば委員","kind":"質問","question":"理由についてお聞きしたので、ちょっとその辺りも。正直今の話だとあまり納得がいかなかったのです。もう１回答弁いただけるようでしたらお願いします。","respondent":"坂野保健予防課長","answer":"従前より、１歳から１５歳というものでやっていたので、ご要望はいただいていたと。今年度については従前どおりでやらせていただいたです。実際問題、１歳からやっている自治体がかなり多いということも現状です。","voiceIndex":147,"id":"exchange-061"},{"speaker":"こしば委員","kind":"質問・要望","question":"課長のご答弁では理由があまり深く聞き出せなかったと思うのですけれども、恐らく当然それは理由があったと思うのです。８区という答弁だったと思うのですけれども、その８区で、既に６か月以上の乳児にもワクチン接種の費用の助成がなされているですので、先ほどもご答弁がありましたが、今後もこの６か月以上のワクチン接種の拡充に向けて強く求めたいと思いますが、改めてご見解をお伺いいたします。","respondent":"坂野保健予防課長","answer":"今お話あったとおり、この８区というものも少しずつ増えてきて８区になっているという現状もありますので、今後、検討の俎上に乗せていきたいと考えております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"こしば委員","kind":"提案","question":"ぜひ強く要望して、時間があまりないので次の質問へ進みます。続きまして、我が会派の鈴木博前議員が、昨年度、繰り返し病気の子どものケアの実践教室の開設を提案してまいりました。","respondent":"石橋品川保健センター所長","answer":"現時点では教室という形での開催は計画しておりませんが、今後その件に関する相談が増えたり、お子さんを持つご家庭からの要望がありましたら、検討していきたいと考えています。","voiceIndex":151,"id":"exchange-063"},{"speaker":"こしば委員","kind":"質問・要望","question":"今お答えいただきましたとおり、アンケートからたくさんの気づきがあったと思います。ぜひその気づきを具体的な政策、施策に置き換えて、検討の先、ぜひ実現に向けて取り組んでいただきたいと思いまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"保健衛生のほうを伺っていきたいと思いますが、この助成金、医師会等々あるわけでありますけれども、この助成対象事業というものは、行政評価シートに一定記載いただいていることもありますが、また、その対象とする事業についての裁量というものは区にあるのかどうか、これを教えてください。","respondent":"若生健康課長","answer":"医師会等への助成金のお尋ねです。こちらにつきましては、様々な、医師会、歯科医師会、薬剤師会、獣医師会、食品衛生協会、環境衛生協会に助成金を支給しているところでございまして、こちらにつきましては、区の要綱に基づいて支給をさせていただいているところです。","voiceIndex":155,"id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"ということは、つまり区が決められるというような理解で今受け止めましたが、そのような中で、款を超えないように伺っていきたいと思うのですけれども、民生費でも伺いました。その背景についてもお声かけいただきます。区の裁量ではありましたけれども、治療や医療機器、講演会、研修等というようになっています。","respondent":"若生健康課長","answer":"現状品川区では、先ほどご紹介いただいたとおり、かかりつけ医、それからかかりつけ歯科医、かかりつけ薬局の定着推進事業のほうで窓口を開設しまして、そういった地域の医療も含めたご相談は窓口として設置していて、ちょっと医療以外で対応できない部分については。","voiceIndex":157,"id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"今ご答弁いただきました。過日の第２回定例会で、産後ケアの拡充という視点で質問させていただきまして、宿泊、日帰り、訪問、それぞれのケアについて、今年度のこども家庭庁発足に伴ういろいろな法令の改正で、助成金の金額であったり、減免の助成の回数であったり、そうしたことを引用させていただきながら、その拡充を求めたところであります。","respondent":"石橋品川保健センター所長","answer":"この改正された要綱や利用者のアンケートを基に、要望のありました利用回数の増加、対象の拡大、こういったところは今検討しているところになりますので、しっかり取り組んでまいりたいと考えています。","voiceIndex":159,"id":"exchange-067"},{"speaker":"つる委員","kind":"提案","question":"乳腺炎の療養支援についても、先の定例会では求めさせていただきました。現状把握や情報収集というところで、ここは時間の関係で答弁は特に求めるものではありませんが、特筆して何かあればいただければと思いますけれども、先ほどの年齢拡大の部分については、もし修正等が、訂正が、それこそ先ほどの話ではないですが、あるのであれば教えていただければと思います。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長","answer":"実施に当たりましては、区内企業、特に区内の女性起業家の方で、エシカルに大変造詣の深い、関心の深い方にご協力をいただきまして、例えばですけれども、ファッションの生地としましては、アメリカの民族衣装の生地やフィリピンの生地。失礼しました。先ほどの答弁ですが、まずは利用回数の増加について検討してまいります。乳腺炎についてですが、母乳ケアを産後ケアの中で拡大するということで、対応を検討しています。","voiceIndex":161,"id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"よろしくお願いします。初めの３つは簡潔にお答えください。ですから、今ＳＮＳがいっぱいあっていろいろ情報発信できるのだから、そこはぜひそういったものを組み合わせてやっていただきたいと思いますが、お答えください。清掃費についてです。今までは平成の時代、きつい、汚い、危険の３Ｋと言われた時代もありました。令和になってどのようなイメージなのでしょうか。よろしくお願います。","respondent":"河内環境課長、若生健康課長、品川品川区清掃事務所長","answer":"こちらの原因はちょっと把握してはございませんが、カラスの捕獲方法も含めて、様々業者のほうも対応しながらというところで。国など様々な情報と併せまして、効果的な周知の方法をＳＮＳも含めまして検討してまいりたいと思います。いろいろな技術革新によって、このようなところも様々改善されてきておりまして、昨今は女性職員の採用など、そういった方向にも進んでいるような状況です。","voiceIndex":165,"id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"カラス・ネズミ対策はぜひ進めていただきたい。これは要望で終わりますので、よろしくお願いします。これはもう要望で終わりますけれども、ぜひよろしくお願いします。地域内で。これ、ＤＸだ何だといろいろ言って、スマホを使えない人はどうするのですかという話になるのです。ポイントカードでいいではないですか。ポイントカードがあるではないですか、まだ。ぜひこれは一元的にやっていただきたいなと。","respondent":"佐藤企画課長","answer":"地域通貨に関するご質問です。地域通貨の内容および効果につきましては、委員ご紹介のとおりということで私どもも認識しております。","voiceIndex":169,"id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問","question":"いろいろ支払い方法もあって、でも、それはもう民間の企業でも同じではないですか。それはもう全国的にだったり、世界的にやられていることであって、私が言っているのはやはり地域でやることなのです。これはもう先ほどからいろいろメリット、デメリットの話も出ていますけれども、私はこれメリットしかないのではないかなと思うのですが、最後にどうでしょうか。お聞かせください。","respondent":"佐藤企画課長","answer":"委員の様々なご提案でありましたり、メリット、デメリットのご紹介をいただいております。そちらに関しましては区として十分認識しておりますので、様々な角度から、収支も含めて、その有効性、活用性も含めて検討してまいります。","voiceIndex":171,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３０３ページの健康診査の中から眼科検診の拡充を求めて、１つは質問したいと思います。このとき、なぜ２回だけなのか、もっと増やすべきではないかということで質問したとき、当時の健康課長は医師会と協議して決めたと答弁されたのですけれども、でも医師会の先生に伺ったら、２回でいいとは言っていないと。それから、検診の委託費が１件当たり幾らなのかも教えていただきたいと思います。","respondent":"若生健康課長","answer":"その後、年齢拡大というところのご要望等も踏まえて、今後見直すべきかどうかということを検討していくというところは、スタンスとしては持っているところですが、現状、医師会からは、そこまで年齢拡大ということについてはご要望が今のところないところでございまして。","voiceIndex":174,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"早期に発見して治療を継続すれば失明することはないので、ぜひとも４０歳からということで書かれております。そのようなことなので、ぜひ早期発見・早期治療、失明させないためにも、検診を４０歳からで毎年に拡大していただきたい。今改めて、リプロダクティブ・ヘルス・アンド・ライツについて、担当部署としてどう考え、捉えているか、認識を伺いたいと思います。","respondent":"若生健康課長","answer":"リプロダクティブ・ヘルス／ライツ、こちらについては女性の生涯を通じた健康を支援する取組の重要性について認識を高めるという観点を持ちつつも、これらの問題について男女がともに高い関心を持って。","voiceIndex":176,"id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"先日も総務費のところで少し質問したのですけれども、安全な中絶の権利、避妊の権利、情報に基づいて産む産まないを自由に決定する権利、そのための性と生殖に関する教育と教育アクセスの権利、性に関する教育を受ける権利、性と生殖に関して、身体的・精神的・社会的に良質な健康環境にある状態を享受する権利、このような形で、権利というところがこの肝、ポイントなのではないかと思うのですけれども。","respondent":"若生健康課長","answer":"権利としての認識があるかですが、先ほどの答弁とちょっと繰り返しのところもありますけれども、そういった生殖に関することや自己決定権、そういったところも含めまして、女性の健康を支援する概念というように、区としては捉えているところです。","voiceIndex":178,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それを自己決定する権利なのだというようなところがこの本質なので、そこをなぜどこで聞いても言えないのかというのが、ちょっと私は理解できないところです。私はこの権利を位置づけて、自治体としても、区民がこれを享受する権利を保障するというところで、環境整備、取組が求められていると思うのですけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"そこで、考え方として、やはりこのリプロダクティブ・ヘルス／ライツの、女性の健康を支援するというような観点での取組の考え方は含んでいるというような認識ですので、今後もそれに基づいて進めていきたいと考えております。","voiceIndex":180,"id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は以前、このようなことに取り組んでいるピッコラーレというところでの取組についてご紹介したのですが、相談の７割が１０代から２０代の若い女性で、多くが生理が遅れている、避妊に失敗した、怖くて妊娠検査を使えない、緊急避妊薬を飲んだ方がいいのかなど、妊娠したかもしれない、妊娠についての相談、単なる知識不足ではなくて、体の仕組み自体も正しく理解していないという、そのような状況で。","respondent":"若生健康課長","answer":"リプロダクティブ・ヘルス／ライツの、考え方として、区としてもそれは十分理解しておりまして、現状でも先ほど申し上げた健康プランの中で取組を進めているほか、保健センターのほうでも妊娠中の悩みに関する相談や、産後。","voiceIndex":182,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような点では、私は大人に対しての性教育というところも、ぜひ取り組むべきではないかと思うのですけれども、体の仕組みも、妊娠の仕組みも、経過、避妊方法、中絶の方法、リプロダクティブ・ヘルス／ライツの考え方、本当に世界から見ても遅れた状況ですから、このことについても取り組むべきだと思うのですが、いかがでしょうか。","respondent":"石橋品川保健センター所長、若生健康課長","answer":"私からは、望まぬ妊娠の件数ということでお話しいたします。こちらの件数に関しましては、統計を特に取っておりませんので持ち合わせておりません。大人の性教育、ちょっと性教育の観点が非常に健康部門でも把握するのは難しいというところは考えております。やはりこれは国全体でいろいろ考えていかなければならない課題ではないかと認識しています。","voiceIndex":184,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう国がとっくに遅れているので、自治体としてもぜひとも取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-078"},{"speaker":"田中委員","kind":"質問・要望","question":"３２７ページ、産業経済費、商店街活性化事業についてお伺いします。関連して、衛生費の３１１、３１９ページにありますカラス対策も絡めてお伺いしていきたいと思います。そのようなことを支援する事業だと考えていますが、その具体的な内容について、ちょっとお聞かせいただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"これは所管としては都市環境部も関わってくるのですけれども、例えば戸越四丁目の、宮前商店街におきましては、地域のにぎわいの維持・創出のための暫定広場の整備といった形で、その整備期間中も、にぎわい創出というものがちゃんとできるようにという配慮もしつつ、また。","voiceIndex":189,"id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"その間も、まずは継続いただいた上で、再三申し上げている道路整備が終わった後の商店街が再生するところまで対応いただけるような支援を、ぜひお願いしたいと思います。カラス対策という事業ではありますが、ハト対策といった視点も含めて、環境課としてこのようなアーケード内の対策が行われるのかどうか確認していきたいと思います。","respondent":"河内環境課長","answer":"アーケード内のハト対策です。ハトにつきまして確認なのですが、鳥獣保護法の中の非狩猟鳥獣ということで、直接的には駆除できないという制約の中で、こういったものの対応を進めているところでございまして、保護の対象となっているところから、なかなか難しい対象です。","voiceIndex":191,"id":"exchange-080"},{"speaker":"田中委員","kind":"質問","question":"現在ある活性化推進事業、アーケード改修などに対する支援事業がありますけれども、そういった観点からも、私はぜひこの事業を活用することで、動物も愛護しながら対策を講じていくということも必要かと思いますが、いかがですでしょうか。","respondent":"小林商業・ものづくり課長","answer":"アーケードやアーチの建て替え、あるいは改修ということにつきまして、またちょっと個別に、どのような建て方をするかというところはまた東京都とも相談しながら、あるいは地元の商店街とも相談しながらということになるかと思いますけれども。","voiceIndex":193,"id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"１つ、既にもう大分前から東京都の事業として行われている事業、私はこのような時代だからこそもっと活用すべきかと思っている事業があるのですが、平成二十数年頃に東京都商店街振興組合連合会の要望も受けまして、商店街の街路灯に広告フラッグをつけたらどうかということで話がありまして、結果的にはつけることができました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは２９９ページ、妊婦健康診査、３０５ページ、精神保健事業、３２５ページ、景況調査委託等、この３点をお伺いしたいと思います。この点について区の見解をお聞きしたいということと、何のための妊婦歯科健診なのか、目的、そこを確認させていただきたいということと、あと目的設定の考え方、また、未受診の要因についても併せてお答えください。","respondent":"若生健康課長","answer":"妊婦歯科健診につきましては、妊婦と産婦を行っているところですけれども、妊婦につきましては、妊娠中、母体の変化によって歯の健康が損なわれやすいというところから、区としてこの重要性を踏まえて実施しているところでございまして、低い理由につきましては。","voiceIndex":197,"id":"exchange-083"},{"speaker":"こんの委員","kind":"提案","question":"これはどうしてなのだろうと。そこで、この受診促進の取組の１つとして、こうしたことはどうでしょうかとご提案をしたいのですが、それは、この歯科健診とともに歯のクリーニング、このときにクリーニングもしてあげますよ、こうしたことを併せてしてあげることによって、この機会にクリーニングをしてくださるのであればと、こうしたことも受診の促進につながるのではないかと考えます。いかがでしょうか。","respondent":"若生健康課長","answer":"ホームページの掲載につきましては、ご指摘いただいたとおり、若干今分かりにくい状況があるというところは認識できましたので、こちらは工夫をしてまいりたいと思います。それから、歯のクリーニングを健診時にやったらどうかということです。","voiceIndex":199,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"精神保健からですけれども、精神障害者の入院制度、これには公費対応の応急入院と措置入院、自己負担の任意入院と医療保護入院がありますが、まず、この医療保護入院について、今現状どのような、件数などが分かれば教えていただきたいということと、あとは当事者やご家族の方、この入院についての実態など、簡潔に教えてください。","respondent":"榎本荏原保健センター所長","answer":"実態ですけれども、医療保護入院につきましては、例えばですが、精神疾患を患われている方が服薬ができなくなりまして、病状が悪化して治療として入院が必要であるということが、ご家族のご意向として出てきて入院をする場合などについて、保健センターではご本人の状況を確認し。","voiceIndex":201,"id":"exchange-085"},{"speaker":"こんの委員","kind":"意見","question":"実態として、今ご紹介いただきました。具体的にご相談をいただいたケースがありまして、その方は精神障害を持っている息子とお母さんと２人暮らしなのですけれども、この息子と生活を共にするために、一緒に生活するために、昼も夜も、いわゆるダブルワークをして生活を維持しなければいけない中で、この精神障害の息子と一緒に暮らしていると。この点についてご見解をお聞かせください。","respondent":"榎本荏原保健センター所長","answer":"民間の救急などを利用されることも承知しております。ただ、この入院については、ご本人の病識がなく、同意がない中で進めていくということもございまして、なかなかその移送費の支援というものは難しいと考えております。","voiceIndex":203,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これ以外に、これは１年なのか、２年なのか、国などもよくいろいろ見ると、経済産業省の方の助成が載っていて、ここはもう８か月ぐらい経営現場研修ということなのだけれども、メルカリなどに行ってきました、このようなこともやりましたなどと載っているのですが、このようなことがやはり品川区でぜひあってほしいと思っていて、この辺のところをぜひもう一度取り組んでほしいと思っていまして。","respondent":"崎村人事課長","answer":"今委員から、ちょっと意味がないというようなお話をいただきましたけれども、人事課のほうで、これまで、コロナ前まで行っておりましたのは、民間企業、特に区内の民間企業に職員を派遣して、民間企業の現場において、行政と異なる考え方や業務の進め方などを学ぶことによって。","voiceIndex":206,"id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"意見","question":"それで、これは多分いろいろなご意見が出て、いろいろな話があって、今、品川区もデジタル庁だとか、東京都、東京競馬、ケーブルテレビだとか、このようなところもあるのでしょうが、以前は聞いたら、例えば東京２０２０大会組織委員会へ派遣をしたら、民間の方もたくさんいらっしゃるから、退職されて二、三人民間へ行ってしまったなどということもあったらしいけれども。","respondent":"崎村人事課長","answer":"先ほどご紹介いただきましたように、職員が派遣に行ったときに、派遣先の事業、事務事業に触れて、そこに感化されてということで退職を決意されたということも事実ですけれども、そういった民間企業や違う団体に行ったものをしっかりと区に持ち帰って。","voiceIndex":208,"id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いします。もう１点、これは関連するかどうか分からないのですが、視野を広げていただくために、副業のことについて少し話をしたいのですが、これをいろいろお伺いすると、公務員には職務専念義務というものがあって、なかなか限られるということがあると思っています。","respondent":"崎村人事課長","answer":"といいますのも、委員から今お話がありましたように、そういった行政とはまた違う仕事を経験することによって、職員としての資質の向上につながるといったものが、今お話しした社会貢献や地域貢献の活動にはあると考えておりますので、こういったものについては。","voiceIndex":210,"id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"意見","question":"役職定年の問題もあったり、再任用の問題もあったり、あとこれもちょっと私はとことん調べていないけれども、あるところまで調べたら、この職務専念義務というものは区の条例によってもある一定程度は免除ができるという項目が出てきて、それを活用しているところもあるというので、どこまでやるか、こちら側の気持ちでどこまでそれをやっていいかということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":212,"id":"exchange-090"},{"speaker":"西村委員","kind":"提案","question":"３０１ページ、産後ケア事業、３２３ページ、中小企業活性化事業費、３２７ページ、商店街活性化推進事業、時間が許せば、３０３ページ、子宮頸がんワクチンについて伺ってまいります。様々委員から質問が既にありますので、私からは具体的に提案をします。産後９週はあっという間にやってきますし、初産だけでなく、経産婦にも拡充していただきたい。改めて拡充の要望をさせていただきたいと思います。","respondent":"石橋品川保健センター所長","answer":"先ほども申し上げましたが、国の要綱が改正されたこともありますので、今後宿泊型の事業についても検討は進めていきたいと考えております。","voiceIndex":214,"id":"exchange-091"},{"speaker":"西村委員","kind":"質問","question":"このような観点からも、ぜひとも、特に経産婦の方の利用は早急にお願いしたいと考えています。日帰りと訪問型の所要時間についてですが、産婦１人につき、訪問型は所要時間が６０分と考えています。日帰りの所要時間２時間半と同じように、時間の拡充を検討していただくことはいかがでしょうか。現状の日帰りと訪問型のサービス内容の違いはどのようなところにあるのでしょうか。区のお考えを伺います。","respondent":"石橋品川保健センター所長","answer":"いろいろ悩みを抱えていらっしゃる方が多いということで、産婦により産後の不安や悩みが違うことは認識しております。それぞれの産後の不安を解消していただけるよう、利用者の声を把握して、ケア内容等も併せて充実を図ってまいりたいと考えています。時間の拡充についてです。","voiceIndex":216,"id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"実際に受けられたお母さんから、６０分以上いてくださったというようなお話も聞いたことがありまして、実際の利用者の方々のお声をぜひとも引き続き聞いていただいて、改善につなげていただきたいと思います。品川区の訪問型は産後６カ月未満、日帰り型は産後４カ月未満と理解しております。港区は訪問、日帰り型ともに、お子さんが１歳未満であること以外の制限はありません。","respondent":"石橋品川保健センター所長","answer":"このような施設をしっかり活用していき、利用者の方に、品川区の産後ケアはすごくいいよねと言っていただけるような事業を目指して頑張ってまいります。","voiceIndex":218,"id":"exchange-093"},{"speaker":"西村委員","kind":"質問","question":"続きまして、商店街活性化推進事業について伺ってまいります。商店街の外国人受入れ環境整備について、すぐに対応いただいた形ですけれども、オリンピック・パラリンピックに向けて、これまでも飲食店等に対して、ホームページやチラシの多言語化、メニュー改正などのメニューがありましたが、コロナ禍で少し取組は落ち着いていると伺っています。７月補正で計上するに至った経緯等をお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"今回の補正予算につきまして申し上げますと、青物横丁と北品川本通りの商店街ということになりますけれども、こういったところで、また品川周辺で、インバウンド向けの対応というものがより進むのではないか、このようなことでより経済の活性化も進むのではないかということで。","voiceIndex":220,"id":"exchange-094"},{"speaker":"西村委員","kind":"提案","question":"総務費でインバウンド対応力の強化について提案させていただきましたけれども、高まるインバウンド需要を品川区として、この産業経済と捉えてどうお考えか、お聞かせいただきたいと思います。具体的には、営業活動でインバウンドをターゲットに取り組む情報発信、多言語化、ＰＲ販路の拡大、サービス醸成などに支援の助成ができないか、現状の取組と区のお考えを伺います。","respondent":"小林商業・ものづくり課長","answer":"今後の対応です。インバウンド対応ということで、この多言語化対応というものがありますし、あと情報発信の事業ということで、多言語化にとどまらず、観光客をどう受け入れていくかという取組は商店街の支援でも重要であると考えております。","voiceIndex":222,"id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"他区だと産業経済費の中に観光施策が入っている場合もありまして、特に力を入れていただきたく、今こそ商機を逃さず、商業的に攻めの施策を検討していただきたいと考えています。特に伸びしろのある地域、やる気のある商店街、商店、団体に注力していただきたいとお願い申し上げます。続きまして、中小企業活性化事業費について伺ってまいりたいと思います。商店街でも使っていただいていると伺っています。","respondent":"小林商業・ものづくり課長","answer":"ただいま省エネルギー対策設備更新助成金についてのお尋ねがございました。内容につきましては、委員のご指摘のとおりでございまして、やはり電気代、ガス代、エネルギー価格の高騰ということに対応しまして、事業者負担をどう軽減するかです。","voiceIndex":224,"id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"大変な反響があると思います。最後に子宮頸がんワクチンについて伺いたいと思います。この区民の方々にまだまだ知られていない、なぜ男性が接種する必要があるのかということ、ワクチンの有効性や安全性をさらに周知する必要があると思いますが、自治体がどのようなことをすれば接種率のアップにつながるのか、何か対策といいますか、アイデアや区のお考えがあればお聞かせいただきたいと思います。","respondent":"坂野保健予防課長","answer":"先ほども少し申し上げたのですけれども、未接種者に対する個別の勧奨など、そのような手をいろいろ工夫して、接種率の向上に努めてまいりたいと考えております。","voiceIndex":226,"id":"exchange-097"},{"speaker":"西村委員","kind":"意見","question":"もし女性も男性も全額助成になったとしましても、接種率が上がらないことにはなかなか意味がなく、供給の少ない貴重なワクチンを廃棄してしまっているという日本全体の問題もあります。そうした実情もありますので、そういったところにおいても、正しく皆さんにこの知識を得ていただくことも大変重要だと考えています。引き続き周知に努めていただければと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひとも区民の皆さんのためにも頑張っていただきたいと思います。次に、このコロナ禍の影響で、どのように事業内容が変更しているのか、現在はどのような活動状況にあるのでしょうか。それもお聞かせください。","respondent":"若生健康課長","answer":"コロナ禍の影響ですが、地区ごとの活動については、令和２年度と令和３年度はほぼ休止といった状況でございましたけれども、令和４年度につきましては、ウォーキングイベントなども再開した地区が出てきておりまして、感染防止を徹底しつつ。","voiceIndex":232,"id":"exchange-099"},{"speaker":"木村委員","kind":"意見","question":"そして今年度、コロナが５類に変わりまして、その後の状況にあまり変化はないと思いますけれども、どこか人の心に余裕が出てきたように見えるのですが、この安心感とは、どのようなことでこの安心感があると思われますか。これもお考えをお聞かせください。","respondent":"若生健康課長","answer":"ふれあい健康塾につきましては、５類移行に合わせてお楽しみプログラムを中止していたものを再開しておりまして、これはとても人気のあるプログラムで、再開を喜ぶ声がたくさんあったというようなお話を聞いておりまして、そういったことも。","voiceIndex":234,"id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"もう皆さんのご努力のおかげで、５類という形で大分収まってきたようには思うのですけれども、まだまだこれからもと思います。次に２９５ページからですけれども、この健康塾、１,０００万円余ですが、先ほどのふれあい健康塾と名前が似ているのですけれども、事業の、この「ふれあい」とはどのような意味があるのか、私の頭では分かりませんが、その意味を教えてください。","respondent":"若生健康課長","answer":"健康塾と、ちょっと名前が似ているふれあい健康塾の違いですけれども、これは健康塾のほうが６０歳以上の区民を対象としておりまして、健康塾のほうは区内のシルバーセンター等の２３か所の会場で、週１回実施しております。","voiceIndex":236,"id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"そのような中で、また会場はシルバーセンターということでありますけれども、定員数はどれぐらいを見込んでいるのか、そしてこの健康塾の最終点、目標はどのような点においての健康づくりなのでしょうか。お聞かせください。","respondent":"若生健康課長","answer":"健康塾の定員につきましては、現在各会場２５名程度で行っております。コロナ対策として、定員を半数程度で２グループに分けてということで、それぞれ隔週で実施しておりまして、これは現在も継続しています。","voiceIndex":238,"id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"会場はシルバーセンターだと思いますけれども、定員数は今言われました二十何名ですか、それを２つに分けるということでありますが、この健康塾の最終点、目標というものを、もう一度お聞かせください。","respondent":"若生健康課長","answer":"目標、到達点というところで、ちょっと繰り返しになってしまうのですが、参加していただいた方に少しでも健康増進をしていただく、体の機能を高めていただいて、生き生きと暮らしていただくと、そういったところを目標、到達点としています。","voiceIndex":240,"id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"若い方々の健康率というものが高いのは当たり前、当然であります。これからこの品川区には絶対に若い力が必要、そして、現在の品川区に、この品川区をつくり上げてきた高齢者の皆さん、今までのこの方々も本当に大事にしていただきたいと思います。そして、人情味あふれる品川づくりをぜひお願いしたいのですが、行政としてのこれからのお考えをもう一度お聞かせください。","respondent":"若生健康課長","answer":"行政としての今後のということでは、こういった健康づくり事業を高齢者の生きがいづくりというところでは福祉部も行っているところではありますけれども、区全体として、こういった健康づくりの施策を横断的に進めていって、区民の健康増進。","voiceIndex":242,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"１点目ですが、款がちょっとよく分からなかったので、私は健康対策という観点で、避暑シェルターの件でお聞きしたいのですが、款が違う、担当が違うとなれば指摘していただきたいのですけれども、そもそもこれ、避暑シェルターの担当はどこになるのでしょうか。お聞きします。","respondent":"勝亦総務課長","answer":"夏場の避暑シェルターにつきましては、総務課で全庁の調整、取りまとめを行っております。","voiceIndex":246,"id":"exchange-105"},{"speaker":"西本委員","kind":"提案","question":"総務課ですね。分かりました。これは多分コロナ禍によって抑えていたところが今まではあったのかもしれないですけれども、今年の夏はコロナが５類になったということでは、特に暑かったですから、活用したいという方々が多かったと思うのですが、どうもそのような雰囲気ではなかった。これに対しての指導や改善提案というものは、総務課でよろしいのでしょうか。","respondent":"勝亦総務課長","answer":"ちょっと実情等については、各施設において管理しているというところで、こちらのほうで具体的な現状、指導という形は取ってはおりません。","voiceIndex":248,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"そこなのです。掲げているのはいいのですけれども、では誰が指導するのですかということなのです。旗を掲げればいいのかということではないと思うのです。ですから、そこは総務課のほうで音頭を取っているのであれば、総務課のほうできっちりと確認をするとか、そして指導するとか、その機能が果たせるように指導していただきたいと思いますが、いかがでしょうか。","respondent":"塚本委員長、勝亦総務課長","answer":"ちょっと款が各所管にわたってしまうので、これは総務課として一応答えられる範囲で答えていただければと思います。避暑シェルターに限らず、区の施設は区民の方が、来やすく、利用しやすく、気持ちよく使っていただけるように対応していただくことは、それぞれの施設でもやっていくことだと考えております。","voiceIndex":250,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと款のどこに入っているか分からなかったところがあって、款を超えた質問だったと思います。失礼いたしましたが、ぜひお願いしたいと思います。次に、２９５ページのＡＥＤ管理費のところですが、今、女性に配慮したＡＥＤの使用方法というものがあります。要は洋服を着てもできるのです。そのようなものをぜひ啓発していただきたいと思うのですが、それは、その情報は行っていますでしょうか。","respondent":"若生健康課長","answer":"女性に配慮したＡＥＤの使用方法ということで、こういったやり方の説明があるということは、私どもも情報をキャッチしているところでございまして、今後ホームページ等でそういったものも掲載できるような形で、工夫をしていきたいと考えております。","voiceIndex":253,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"裸にされることは。ですから、そのような配慮を、そういうやり方があるのですから、それを広めていただきたいなと思うと同時に、それからマップ、ＡＥＤのマップというものがあります。ただ、これは使いづらいです。ですから、実際に使えるような形にしていかなければいけないということは、ＡＥＤがどこにあって、どのように使えるのかというところまで訓練が必要になるかと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"２点質問いただきました。啓発というところについて、町会などといったところで行われているところにということだったのですが、ちょっと周知の方法については今後検討してまいりたいと考えております。","voiceIndex":255,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"分からない人が大半だと思います。どこにあるのか。一々見ますか、アプリを開いて。ですから、まず啓発をぜひお願いしたいと思います。次に、２９９ページのすくすく赤ちゃん訪問事業です。これは今年度、おむつ等育児用品宅配定期訪問というものがあります。これの違いは何でしょうか。それぞれ目的があると思うのですが、その目的、同じであればこれを統合していくのでしょうか。","respondent":"石橋品川保健センター所長","answer":"既存の母子保健指導事業、こちらと新規の事業です。しっかり相互に連携を取りながら実施してまいりたいと思っておりまして、すくすく赤ちゃん訪問を統合するということは今のところ考えておらず、別々の事業とはなりますが、連動して実施をしていきたいと思います。","voiceIndex":257,"id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"くれぐれも二重行政、二重にするということのないように、それぞれ特徴を見いだして、協力しながらお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"３２９ページのプレミアム付区内共通商品券発行助成では、令和４年度は商品券、紙で４億円と秋は６億円、足して１０億円ですかね。それから、キャッシュレス決済のポイントも、一昨年度に引き続いて行われて、これは５億円というところで、ここら辺の確認なのですが、これは現状の確認です。それから、キャッシュレスも行われました。以上、様々お聞きしましたが、よろしくお願いいたします。","respondent":"坂野保健予防課長、舩木生活衛生課長、小林商業・ものづくり課長","answer":"そういうふうにご理解いただければ。これ、１分、２分で説明できるレベルではないものですから、申し訳ございません。令和５年度のプレスで発表しております新型コロナウイルス感染症対応の検証と健康危機管理体制の構築ですけれども、これはプレスの内容のとおり。この中で、商連に加盟している、加盟していないというところは、今データがございませんので、こちらはお答えができないところです。","voiceIndex":262,"id":"exchange-112"},{"speaker":"若林委員","kind":"意見","question":"コロナの対応については、取りあえず長い説明を聞かないで、短い説明の中でざっくりと理解をさせていただいて、いずれにしても品川区はコロナの対応について、速やかに検証、計画を立てるということで、しっかりまた委員会等でご報告があるものと期待をしております。そういったものを中心に、しっかりと私はまた見詰め直す時期ではないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":266,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２３ページのシルバー人材センターについてお尋ねします。１０月からインボイス制度がスタートしました。シルバー人材センターの会員の皆さんの仕事との関係についてお尋ねします。当時の商業・ものづくり課長がこうおっしゃいました。そこで、シルバー人材センターの事務局の方々はご苦労されていると思いますが、仕事の発注元と契約の状況について、現在どのような状況かお伺いします。","respondent":"小林商業・ものづくり課長","answer":"先ほどご指摘のありました会報誌にも書いてありますけれども、１０月以降、会員本人がインボイスの事業者として登録する必要はないこと、登録していなければ、配分金に含まれる消費税相当額はセンターが納税するので、会員本人が納税する必要はないことというような対応で。","voiceIndex":268,"id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"会員の方に影響がないようにというお言葉が今ありました。そこで、発注元の大きなところとして、品川区があります。施設の管理や清掃等、そのほか多岐にわたって発注していますが、予算措置について、今のようなお話を含めて、区のほうが、つまり発注元の区が、十分確保されているかということをお尋ねします。徹底されているのか。そういった状況の中で、区で十分確保されているのでしょうか。","respondent":"遠藤財政課長","answer":"シルバー人材センターの委託契約のお話かと考えています。事業がいろいろとありますので、それぞれ所管のほうで今見積りを取って、来年度予算という形でやらせていただいている部分と、あと、昨年度から既にそういう話は出ているところです。","voiceIndex":270,"id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、会員の皆さんに影響が出ないように、今、課長におっしゃっていただいたように、今後の発注元としての区の立場というのは大変重要になってくると思います。先ほどの約１２億円の中でも相当な部分を占めております。シルバー人材センターは、昭和５２年に設立され４５年が経過しました。今、財政課長にお話しいただきましたけれども、所管の商業・ものづくり課長としての支援に対する決意を伺います。","respondent":"小林商業・ものづくり課長","answer":"引き続き、こういった活動について支援してまいりたいと考えております。","voiceIndex":272,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、約１億８,０００万円を要求したのですが、約２,２００万円を減らされた状況で、今年度の運営は円滑にいっているのでしょうか。","respondent":"河内環境課長","answer":"努力してやっている状況でございまして、お客様に迷惑をかけていないというところで認識しています。","voiceIndex":276,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"意見","question":"増やしたのは、どうして増やすというふうに要求したのかというところをお尋ねして、その部分が、約２,２００万円も要求から減らされたけれども、大丈夫なのかと。努力されてやっているというので、円滑にいっていることは分かりましたが。どの点を増やそうとしたけれども削られて、それでも、どの点を増やそうとしたというところをお尋ねしています。","respondent":"河内環境課長","answer":"視察などの対応で事業担当も必要なのですが、一方で、やはりご来場者を賜るためには広報活動の活性化ということも大事になっております。","voiceIndex":278,"id":"exchange-118"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書３２５ページ、関連して主要施策の成果報告書１７ページの、どちらも事業承継支援事業について質問いたします。日本の企業のうち９９％を占める中小企業は、雇用の技術の担い手として日本を支える重要な存在でありますが、我が国全体の高齢化が進む中で、中小企業においても経営者の高齢化が進んでおります。そこで、最初にお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"実際の取組としまして、事業承継というのは、親族で引き継ぐケースですとか、従業員の方に引き継いでいただくケース、あるいは社外という、幾つか類型がありますけれども、品川区ではいずれの部分についても認識しつつ、セミナー、後継者塾、専門家の相談派遣、あるいは。","voiceIndex":282,"id":"exchange-119"},{"speaker":"まつざわ委員","kind":"質問","question":"事業承継に幾つかの類型があるというご説明がありました。私の周辺でも親族内の承継のお話を耳にしたことがありますが、家族や親族間の承継といっても、そう簡単に進むものではないようです。そこでお伺いします。親族内承継は具体的にどのようなことが課題になるのか。そうした難しい課題に適切な助言や指導を行っていくために、どのような専門家をそろえているのか、お示しください。","respondent":"小林商業・ものづくり課長","answer":"ただいまご指摘のありました親族内承継ですけれども、やはり親族が引き継ぐという中で、親族の中、あるいは従業員、取引先の合意の取付けというのがまず必要ですし、また、経営者、取締役代表権の交代手続ですとか、あるいは株式、事業用資産の相続・贈与など。","voiceIndex":284,"id":"exchange-120"},{"speaker":"まつざわ委員","kind":"質問","question":"区では円滑な事業承継の支援のために、セミナー、また後継者塾などを開催して、専門家派遣相談、そして、事業承継の設備投資助成などを行っている、そういうご説明でしたが、これら全体の要は事業の実績というのはいかがでしょうか。私の感覚では、商業・ものづくり課で十分に力を入れていただいているというのは評価していますが、成果報告書でもありますこの執行率が伸び悩んだ理由についてお示しください。","respondent":"小林商業・ものづくり課長","answer":"一方で、一番多く予算を確保している部分、設備投資支援というのが、製造業ですと最大５００万円、助成率２分の１ですけれども、こちらが新型コロナの中で投資に対するやや慎重な動きも出ているところでございまして、今後。","voiceIndex":286,"id":"exchange-121"},{"speaker":"まつざわ委員","kind":"質問","question":"要は、事業承継の中でも、設備に係る投資というのが大分多く占めていたけれども、新型コロナウイルスの影響で減りつつあったということですよね。すなわち後継者が親族内や社内にいない場合でも、社外の方の承継という可能性や選択があるということを示していると思いますが、品川区の今の支援制度では、社外への引継ぎも相談の対象となるのでしょうか。ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"ご指摘の社外への引継ぎにつきましては、この３つの分類の中でもやはり一番難しい分類と言われているところでございまして、品川区でもこの事業承継の選択肢の一つとして、支援対象に位置づけているところです。","voiceIndex":288,"id":"exchange-122"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"最後になりますけれども、これは事業承継に限らないお話ですけれども、実は東京商工会議所の方からも要望がある話の中で、区内のこの産業支援間の連携が大変重要であるのかなというのは、団体要望のヒアリングをお聞きして私が感じたことであります。","respondent":"小林商業・ものづくり課長","answer":"こういう取組が、会員か非会員かということに関わらず、区内企業、区内事業者の皆さんの力になると考えておりますので、こういう団体間の連携というところ、区でも必要な取組をやっていきたいと考えています。","voiceIndex":290,"id":"exchange-123"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ商業・ものづくり課が中心となりまして、そういった企業支援機関をつなぐかけ橋になっていただくことを要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-124"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは３０１ページ、不妊治療助成事業を伺います。保険適用と東京都の特定不妊治療、先進医療に対する助成、これでかなりカバーできているとは私も考えるのですけれども、ただ、やはりそれでも、不妊治療というのは１回で終わるものではなくて、どうしても何回もやっていく。こうした助成について、品川区でもご検討いただきたいと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"今後、不妊治療については、どういったところが足りていないのかとか、どういうところに負担がいっているのか、これは男性の治療も含めまして、全体的に区の方で検討して、いろいろ調査をしながら考えてまいりたいと考えています。","voiceIndex":294,"id":"exchange-125"},{"speaker":"松本委員","kind":"質問・要望","question":"相談体制をぜひ整備していただきたいという点が１個と、これも質問として、調査のところですが、やはりニーズの調査というのは必要だと思っておりまして、どういうふうに調査するかですけれども、例えば婚姻届を出された方に対して、そのときにアンケート用紙をお渡しして、それでどういうニーズがあるかという調査をしていただけないかなと思うのですけれども、この２点、よろしくお願いします。","respondent":"若生健康課長","answer":"調査について、これは妊娠届け時などにアンケートとか、そういったことも方法としてあるかなとは思いますが、かなりセンシティブなお話にもなってくるところですので、取り方とかも、なかなか一律に取るのは難しいところかなと感想を持っているところですが。","voiceIndex":296,"id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"調査の仕方としては、不妊治療に特化した質問の仕方だけではなくて、例えば子育てに関する質問の中で、子育ての意向ですね。最後に、これは自分自身の知識もそうですけれども、やはり年齢とともにどうしても妊娠率というのは下がっていく。では、どういうふうにこの知識を高めていくのかというところで、これはやり方に気をつけないと、やはりライフプランとの関係で難しい。","respondent":"若生健康課長","answer":"他自治体の事例も踏まえて、検討してまいります。","voiceIndex":298,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"私は３２９ページ、共通商品券普及促進事業と、あと３２７ページ、運送事業者等燃料費高騰対策支援金についてお聞きしたいと思います。区内産業の現状について、区として今どのように捉えられているか、ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"区内経済に関して幾つか課題があると考えています。１つ、一番大きいのは、やはり今物価高騰をめぐる対応ですとか、あるいは新型コロナの後の景気回復の状況です。","voiceIndex":301,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"もう一度お聞きしますが、実態、例えば飲食業、その他様々な企業があります。お店、工場、製造業、建設業、そういう全体を見てどう思われますか。もう一度お聞かせください。","respondent":"小林商業・ものづくり課長","answer":"ただ、その中で、やはり先ほど申し上げたような経営課題もある中で、中小企業をめぐる課題といいますか、経営状況はまだ厳しいものがあると考えておりまして、その中で必要な経済支援、対策というのは考えていく必要があると考えております。","voiceIndex":303,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"第一に、民間で働く人の平均給与は４４３万円。もう３０年間で３０万円も下がっている。そして、租税負担率、社会保障負担率、合計した国民負担率が今年度は４６.８％となり、国民負担増大の見通しを示している。これは国が示しているわけです。値上げ品目数は今日まで３万品目もある。どこにあるのかな。では、いきなり来たからどうなのだと。それが現状ではないですか。もう一度ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"それを数値化する中で、例えばこの１０年、２０年というスパンの中で、どういう景況感にあるかというものを示すものですが、これが一つ、我々としては景況感を示す基本データで考えてはおりますけれども、それ以外に、特にやはり規模感で見ますと。","voiceIndex":305,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"実際、今、国民の中では所得格差が本当に広がっております。広がる一方で「億り人」と言われる富裕層も増えていますが、４００万円、３００万円、２００万円以下の所得層も本当にかなり増えているという現状です。さて、プレミアム付区内共通商品券を品川区で発行していますが、これは産業振興政策なのですか。簡単に教えてください。","respondent":"小林商業・ものづくり課長","answer":"幅広い意味では産業振興といいますか、区内経済の下支えのためにやっているものです。ただ、その中で、実際、やはり商店街の振興ということでやっている側面もあります。","voiceIndex":307,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"これに対して何人の方が購入しているのですか。そして、発行数はいつも完売しているのでしょうか。教えてください。それで、例えば先ほどもほかの方が質問していましたが、この商品券での購入品目です。そういうデータというのはあるのでしょうか。教えてください。","respondent":"小林商業・ものづくり課長","answer":"令和４年度の実績というところで申し上げたいと思います。春のほうが当初４万冊ということでこれを発行いたしました。秋のほうが当初４万冊でしたけれども、昨年の新型コロナという状況もございまして、６万冊に増刷して発行したところです。","voiceIndex":309,"id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"これは、最高１人８冊なのですか。その分まで買えるということは、これを買うということはお金に余裕があって、ごく僅かの区民が購入して、区の補助分について恩恵を受ける、そういう仕組みのものではないのですか。区の予算でごく僅かな区民の皆さんに恩恵を与える仕組みをつくっているというのは、私はおかしいと思うのですが、どうでしょうか。教えてください。","respondent":"小林商業・ものづくり課長","answer":"実際にこれがどう使われているか、年代別とか性別とかも購入データから取っているわけですけれども、実際にこの中で、地元の商店街の中で、１０％あるいは２０％というプレミアム率の中で、日常の買物、先ほどの購入データですけれども、一般的なぜいたく品と言われるものよりは。","voiceIndex":311,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私が言っているのは、ごく僅かな人にそれだけ恩恵を与えていいのですかということなのですよ。だってご高齢者が買いに行けますか。申し込めますか。そうすると、やはり動ける人、お金に余裕のある人でないと最初から金を出せませんよ。そこを言っているのですよ。今の時期はもう変えるべきではないのですか。経営資源として、品川区において、このほかに何か事業支援はしているのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"これは、将来的に電気代・ガス代がこの後も高騰が続くと考えられておりまして、現在、これを下げるような設備投資をする際に、上限８０万円ということで区で支援しておりまして、地元の商店街の中でいきますと飲食店とか、あるいは製造業と。","voiceIndex":313,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"設備投資をする余裕がある会社はいいですよ。違うのではないですか。これ、区の管理下にある介護、保育、幼稚園、学校もそうですが、これもそれぞれ関わっている個々人の事業所に対して、インフレスライドというのは適用しているのですか。燃料費が上がっているから、物価が上がっているから、上げてやっているのですか。そういう補助というのが、支援が大事ではないのですか。教えてください。","respondent":"塚本委員長、小林商業・ものづくり課長","answer":"やや款を超えているところもあるのですが、商業・ものづくり課としての範囲でお答えいただければ。どの範囲でお答えできるかですけれども、やはり今、物価高騰というものがあります。ですので、品川区の産業支援の助成金ですとか、そういうものの中も、こういう動向を踏まえて考えていきたいと考えております。","voiceIndex":315,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３１１ページの温暖化対策事業について、３０５ページの新型コロナウイルス感染症対策について伺います。温暖化対策です。一般質問で、区の取組を着実に進めるために年度ごとの目標を立て、毎年検証を求めました。省エネ機器と創エネ、リサイクルなど、それぞれについて今年はどれだけ進めるのか、どこまで進んだのかということを検証するべきだと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"中間目標といいましても、２０３０年のカーボンハーフがありまして、そこに向けてという話になるのですが、削減状況の中のチェックポイントといたしまして、やはり年間削減量の平均値でありますとか、あるいは、他区の削減状況との見合いだとか、そういったところを含めまして。","voiceIndex":319,"id":"exchange-136"},{"speaker":"のだて委員","kind":"質問","question":"全力で頑張っているということですけれども、どれが主役になるか分からないという話もありました。それぞれをやはりどこまで進めていくのかということを、しっかりと計画持って進めていくということが、２０３０年のカーボンハーフを実現するということになっていくと思うのです。そうした取組で本当にカーボンハーフを実現することができるのかと思いますので、チェックの仕方をまた伺いたいと思います。","respondent":"河内環境課長","answer":"こういったところの各分野の目標値に向かいまして、これは環境基本計画の中にも分割して書いてありますので、そういったところを含めまして、目標に向かいましての進捗管理をしっかり行いたいという考えです。","voiceIndex":321,"id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"年間としては６８ｋｔですか、削減をしていくということですけれども、それをどういった取組で進めていくのかということを具体化していくことが、着実にカーボンハーフに向けて進めていくということになると思います。それぞれを具体的にどう進めていくのかということを、しっかり区民にも分かるように示していただきたいと思うのですけれども、いかがでしょう。","respondent":"河内環境課長","answer":"エコルとごしの環境の講座でありますとか、多角的なところで皆さんに啓発を行い、皆さんに、例えば家庭で言いますと耐久消費財、２０年に一度、エアコンでありますとか冷蔵庫でありますとか、そういったもののチャンスがめぐってまいります。","voiceIndex":323,"id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々ご説明がありましたけれども、しっかりと区民にも分かるように、カーボンハーフに向けて実際進んでいるのか、進んでいないのかということを示して、やっていっていただきたいと思います。その中で、具体的な取組として太陽光発電について伺います。一般質問では、太陽光発電と蓄電池設置助成額の拡充を求めました。この需要等を踏まえ検討というのはどういうことなのか、どういう意味なのか、伺います。","respondent":"河内環境課長","answer":"年間におきましては、今まで区民の中で年間４０件前後の補助ですが、令和５年度になりまして、蓄電池の数も相当伸びてきてまいります。そういった需要を捉まえまして、伸ばせるところは非常に伸ばしていき、削減に向けて進めてまいりたいと考えているところです。","voiceIndex":325,"id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"伸ばせるところは伸ばしたいということですので、ぜひ太陽光発電も含めて、伸ばしていっていただきたいと思うのです。今、区の件数は、令和４年度は助成件数４１件ということでした。品川区として、今、増えてきて４１件ということですけれども、なかなか進まない、その原因は何だと考えているでしょうか。１つは周知が弱いのではないかということも思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"現在の価格設定におきましては、他区の状況も踏まえまして、平均的なところを取りまして、インセンティブに働くかどうかの検証も含めて進めておりますが、そういったものが効くというような状況でありましたらば、検討を進めてまいりたいと思いますが、現在のところ。","voiceIndex":327,"id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"区がなかなか進んでいない原因、課題も後でご答弁いただければと思うのですが、実際にインセンティブになるかというお話がありましたが、やはり助成額が多くなれば、その分、つけようという人も多くなると思うのです。そうしたところでぜひ周知も進めていただきたいと思いますし、設置をさらに促進していくためにも助成額の拡充を求めたいと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"そういったところの援助も必要だと思いますが、一方で、普通の方が必要な脱炭素に関しての環境技術の普及など、そういったところにも手を加えなければいけません。そういったところから、助成額につきましては、適正なレベルでまずは進めてまいりたいと考えているところです。","voiceIndex":329,"id":"exchange-141"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのために、パネルを屋根に載せるためには補強工事が必要だということで、このことにも助成をすべきだと求めましたけれども、区は、住宅改善工事で耐震補強の項目があるので、そっちを使ってくださいということでしたけれども、住宅改善工事はエコ＆バリアフリーで、いろいろなものにも使えるということでして、条件は２０万円ということですから、これでは足りないというか。","respondent":"河内環境課長","answer":"設置の費用につきましては、ペロブスカイト型がシリコン型と拮抗するのも間近ではないかという予想も出ておりますので、そういった普及に向けての分母の開拓ではないのですが、適正な情報を発信しながら、区民の方にご判断いただきながら進めていくことが大切かと考えています。","voiceIndex":331,"id":"exchange-142"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは当然、求めておきたいと思います。今のは創エネの問題で、今度、省エネ対策としても、断熱化を進めてほしいということで求めてきました。義務化がされれば助成を考えるということなのか、それまでは実施しないということなのか、伺いたいと思います。","respondent":"河内環境課長","answer":"つまり今後、外皮性能の工事をやるに当たっては、それを選ばざるを得ない状況もあるという中で、外皮性能の向上か、あるいは中の熱源機器などＣＯ２が発生する電力機器を変えるのかというようなところで、マルチに目で見ながら総合的に勘案する必要があるというところで。","voiceIndex":333,"id":"exchange-143"},{"speaker":"のだて委員","kind":"質問・要望","question":"コロナです。感染が疑わしいときに希望者が検査をできるように、地域センターなどで抗原検査キットの配布をしていただきたいと思いますが、いかがでしょうか。医療機関でも気軽に受けられるように、公費負担を続けるように国に求めていただきたいと思いますが、いかがでしょうか。ですので、医療機関へのエールも込めて、国に公費負担を続けるよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"公費負担の復活というか、そういうところかと思うのですけれども、これも国の決めですので、これを元に戻してくださいみたいな要望を区からする考えはございません。","voiceIndex":335,"id":"exchange-144"},{"speaker":"のだて委員","kind":"質問・要望","question":"５類に引き下げられて何もやらないというご答弁でしたけれども、やはり検査をすることで、自分がかかっているかどうかというのが分かるわけで、そうすることで、外出を自粛するということで感染拡大防止にもつながると考えますけれども、いかがでしょうか。そのためにやはり抗原検査キットの配布をしていくべきだと。","respondent":"坂野保健予防課長","answer":"しかしながら、検査をたくさんやって、それで感染予防につながるかという研究に関しては、どちらかというと否定的な研究のほうが今は多いです。なかなか検査を無料にしてアクセスを改善したから、それで感染が広がらないというのは、今のところは否定的な考えです。","voiceIndex":337,"id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"よろしくお願いします。午前中、会派のひがし委員からも質問いたしましたが、産褥期へのケアの拡充を求めて質問いたします。今は施設の制約があってお食事が出せないというのは承知しておりますけれども、申込みのしやすさと、それから、施設をどうにかしなければいけませんが、拡充を求めたいと思います。そういうことをこの産後ケアについても検討していただけないかと思うのですが、見解を伺います。","respondent":"石橋品川保健センター所長","answer":"助産師会の活用ということになりますが、今後、助産師会を含めた活用については、関連団体、関係所管と連携しながら、産褥期を含めた女性の出産後の総合的な支援について検討してまいりたいと考えております。","voiceIndex":340,"id":"exchange-146"},{"speaker":"吉田委員","kind":"提案","question":"今年３月の予算特別委員会で組成調査のことを伺ったところ、品川区清掃事務所長から、組成調査については、一般廃棄物処理基本計画を作成しております。先ほど ＣＯ２削減のことが出ましたけれども、やはりごみは増えれば結局燃やすわけですから、それはＣＯ２を発生させるということにつながります。ぜひその点も踏まえて、組成調査を行っていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"組成調査の件です。内容については、委員から詳しくご説明いただきましたので、今後の組成調査の件についてお話をしたいと思います。","voiceIndex":342,"id":"exchange-147"},{"speaker":"吉田委員","kind":"提案","question":"それで、廃棄物減量等推進会議の正副会長が２人おられますね。費用がかかるというのですけれども、区が単独でやろうとするからいけないのではないか。大学と連携してはどうですか」というご提案をいただきました。具体的な大学名を挙げてくださったのですが、大学などと連携して組成調査を行い、共同研究のような形でごみ減量を図ることを検討してはどうかというご提案なのですが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"今後、ではどのタイミングで組成調査をするかというのは、非常に難しいところでもありますので、そういったところも他区の例も含めて、大学との連携等も今お話いただきましたので、そういう広い視野を持ちながら、研究していきたいと考えています。","voiceIndex":344,"id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"もうないよと。ただ、多摩地域の人たちは、極端な話をすると自分の家の隣に処分場ができるとか、そういうようなことになるので、すごく自分事として、住民もみんなで話し合って議論するのですけれども、どうも２３区は、清掃一部事務組合がやっているということもあるし、それから、海のほうにというのがあります。それがどうしても必要だということです。見解をお伺いします。","respondent":"品川品川区清掃事務所長","answer":"そういう中で一番何をしていけばいいかというところは、リサイクル品目を拡大していく。そういうことで資源化率をどんどん上げていって、燃やすごみの量を減らしていく。こういったことも一つ、大事な目線ではないかなと考えています。","voiceIndex":346,"id":"exchange-149"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、３１１ページ、品川区環境基本計画改訂等経費、３１３ページ、地域エコ活動推進事業から使い捨てプラスチック削減推進、マイボトルの利用促進とウォータースタンドの設置について伺ってまいります。協定では何基まで無償提供が可能なのか、また、３基は設置から８か月程度が現在経過していますけれども、利用状況や利用者の感想を教えてください。","respondent":"河内環境課長","answer":"契約につきましては５基ですので、今、２基の設置に向けて調整をしています。","voiceIndex":349,"id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここから質問ですが、ウォーターサーバーの設置について、先ほど無償提供のあと２台があって、それを今検討されているということでしたけれども、できればそれを超えて、ペットボトルのプラスチック削減とか、そういう観点から、区民ニーズのある場所への拡大をぜひ行っていただきたいと考えていますけれども、今後の展開についてもお知らせください。","respondent":"河内環境課長","answer":"町場におきましては、いろいろなところでウォータースタンド社の同じ製品が展開されている状況ですので、今後も連携した取組を視野に、進めてまいりたいと考えているところです。","voiceIndex":351,"id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問","question":"」と。マイボトルの使用者の方というのは、割と今、肩身の狭い思いをしていて、そういう給水器があっても、そこでマイボトルに入れたら怒られてしまうのではないかとか、そういうところで、非常に分かりやすいものを、品川区としても掲示というのですか、そういうものをウォータースタンドに限らずできたらいいのではないかというアイデアもありました。その点についてのご見解も伺いたいと思います。","respondent":"河内環境課長","answer":"こういったプラスチック削減に向けての事業ですが、やはり皆様の意識の中で利用しやすさだとか、これを利用することによっての格好よさというのか分かりませんが、誇りを持ってこういったものに取り組めるようにということで、有名人の方との連携なども含めまして。","voiceIndex":353,"id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"環境の取組は苦しいものではなくて、楽しくわくわくするものでぜひ進めていっていただきたいと思います。時間が若干ありますので、各種がん検診、アピアランスケア支援の現状と制度拡充について伺います。本年７月３日からがん患者への支援として、待望のアピアランスケア事業がスタートして、３か月がたちました。申請者の性別の内訳、がんの種類が分かれば、それも教えてください。","respondent":"若生健康課長","answer":"アピアランスケア事業は、今年度７月から開始しております。申請件数を月ごとで申し上げますと、７月が２８件、８月が１０件、９月が、９月２０日時点で９件ということで、合計で申請は４７件いただいているところです。","voiceIndex":355,"id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ざっと今伺うと、４７件あって、１０種類ぐらいのがんの姿が見えてまいりました。申請された内容から、多種多様ながんと闘う、またがんと共存共生をしている区民の姿が見えてまいります。これは耐用年数が半年なのですよ。これは買い替えなければいけない。１６０件の予算を積んでいるので、今年度はまだ若干時間があるので余裕はあると思うのですが、ぜひこの拡大についてお伺いしたい。","respondent":"若生健康課長","answer":"区としては、７月に始めたところで、まだ３か月余りというところで、先ほどご説明した状況ではあります。今後、今年度の実績をしっかり確認して、利用者の声とか、そういった状況、金額ですとか、また品目、そういうところも含めまして、検討していきたいと考えております。","voiceIndex":357,"id":"exchange-154"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"３１５ページ、粗大ごみからのリユース事業、時間があれば同ページの資源化センター管理運営費についてお伺いします。粗大ごみからのリユース事業についてお伺いします。令和４年度から粗大ごみのリサイクルを始めているということで、これは大変すばらしい事業だなと思っています。","respondent":"品川品川区清掃事務所長","answer":"粗大ごみリユースのほうは、さすがに１点１点のものがありますので、そういったものについては、もう本当に数パーセントというような形で、あまり数字的な効果はないと、こういった状況です。","voiceIndex":360,"id":"exchange-155"},{"speaker":"せりざわ委員","kind":"提案","question":"一方で、今お話しいただいたように建築資材としてはよく使われるもので、事業者用のリサイクルになっているのかなと思って、ぜひ区民が親しみを持てるようなリサイクルに何かできないかなと思って、これは提案なのですが、これから、我々の会派でもいろいろ要望させていただいたドッグランというのを、品川区で作っていこうかという話もあると思うのです。","respondent":"品川品川区清掃事務所長","answer":"これも、補正予算を組みまして、１２月から粗大ごみの中から衣装ケースもピックアップしまして、こちらをまたプラスチックの処理業者に、こちらは歳入として、買い取っていただけるという形で進めていく予定です。","voiceIndex":362,"id":"exchange-156"},{"speaker":"せりざわ委員","kind":"提案","question":"今日、冒頭、えのした委員から、今日は何の日というお話があって、その後、本家本元でありますつる委員からも、今日は何の日というお話があって、そんな話を聞きながら、私にとって今日は何の日だろうなというのを、いろいろ議会で確認していたのですが、２年前の２０２１年の１０月６日、実は品川区清掃事務所長と決算特別委員会でやり取りをさせていただいて、その答弁をいただいて。","respondent":"品川品川区清掃事務所長","answer":"ですので、事業系のごみについてどういうふうにやっていくかというところが一つ問題点にはなるのですが、多分、啓発というような形で区としても進めていく方向になるのかなとは思っております。","voiceIndex":364,"id":"exchange-157"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"それをぜひ集めていただいて、２年前の当時は、私、別にＸ ＪＡＰＡＮのファンでもないのですが、クリスタルグランドピアノを作りませんかというお話をさせていただいて、新庁舎ができたときに区民の皆さんと弾けたらいいのではないですかという話もさせていただきましたが、例えばこれからシティマラソンなどがあって、その表彰台に使うとか、いろいろなやり方が考えられると思うのです。","respondent":"品川品川区清掃事務所長","answer":"やり方はいろいろあると思いますので、ほかの市区町村などの対応も研究し、あとアクリル板で一体どういうものができるかというところも非常に大切だと思います。そういったところもいろいろ調査しながら、申し訳ございません、研究をしていきたいと思います。","voiceIndex":366,"id":"exchange-158"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今は目の前にアクリル板はもう見当たらなくなっていると思いますが、各町会、あとはお店も会社も、もちろんこの役所も、まだ保管している年だと思うのです。だんだん邪魔になってきて、いずれは捨てられてしまうと思うので、その前の段階で、今年もしくは来年が最後の研究ではなく検討の段階だと思いますので、そこの力をぜひ込めていただいて、リサイクルを推進していただければ。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-159"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":124751,"voices":369}}]);
